pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to zero is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Penalize dead space quadratically, but only if it is truly unusable
        // (smaller than the minimum plausible item).
        let dead = post_residual as f64;
        score += 0.15 * dead * dead / bin_capacity as f64;
        if post_residual < 10 {
            score += 20.0; // tiny sliver: wasted bin space
        }
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.1 * next_item_size as f64;
    }
    // Lookahead penalty: if next item cannot fit here but barely fits elsewhere,
    // this bin is less attractive.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score -= 2.0 * open_bins_count as f64 * 0.1;

    // Compare residual to the mean residual: bins below average residual
    // (already tight) are good targets; above-average bins keep flexibility.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate logic: only attractive when the item is large and
    // existing residuals are poor fits, or early in the stream with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
