            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): near-miss rescue refinement.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): dead-space ratio sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let half_next = next_item_size as f64 * 0.5;
        if dead > half_next {
            let excess = (dead - half_next) / (next_item_size as f64 - half_next).max(1.0);
            score += 7.0 * excess * excess * excess * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 45): variance-collapse drain.
    if post_residual > 0 && fitting_bins_count >= 2 && open_bins_count >= 3 {
        let pool = mean_residual.max(1.0);
        let below = (pool - dead) / pool;
        if below > 0.0 && below <= 0.5 {
            let weight = ((open_bins_count as f64).ln() / 4.0).clamp(0.25, 1.0);
            score -= 4.0 * (1.0 - below * 2.0) * weight * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 45): residual-absorption pairing.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let absorb = 1.0 - (dead / mean_residual.max(1.0)).clamp(0.0, 1.0);
        if dead <= mean_residual {
            score -= 3.0 * absorb * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 46): dead-space floor sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pr = dead;
        let half_next = next_item_size as f64 * 0.5;
        if pr > half_next * 0.9 && pr <= next_item_size as f64 * 0.75 {
            let band_pos = (pr - half_next * 0.9) / (next_item_size as f64 * 0.75 - half_next * 0.9).max(1.0);
            score += 9.0 * band_pos * (1.0 - band_pos) * 4.0 * (0.4 + 0.6 * progress);
        }
        let pool = mean_residual.max(1.0);
        if pr < pool * 0.9 && pr > 0.0 {
            let absorbability = 1.0 - (pool - pr) / pool;
            score -= 2.5 * absorbability * (1.0 - (fitting_bins_count as f64).min(5.0) / 5.0) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 46): residual-decay governor.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 4 {
        let fleet_avg_dead = mean_residual;
        if fleet_avg_dead > next_item_size as f64 * 0.6 {
            let excess_fleet = (fleet_avg_dead - next_item_size as f64 * 0.6) / cap;
            let tight_gain = 1.0 - (dead / cap);
            score -= 5.0 * excess_fleet.clamp(0.0, 0.3) * tight_gain * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 46): fresh-bin dead-space floor gate.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_res = (bin_capacity - item_size) as f64;
        let liability = fresh_res / cap;
        let pool_frac = mean_residual / cap;
        if liability > 0.35 && pool_frac < 0.20 && fitting_bins_count >= 1 {
            score += 10.0 * (liability - 0.35) / 0.65 * (0.5 + 0.5 * progress);
        }
        if fresh_res as u32 == next_item_size {
            score -= 4.0 * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 47): fleet-residual sweep — when the fleet mean residual
    // cannot host the next item but this bin's post-residual can, reward
    // this bin as the designated receiver; this drains the fleet toward
    // fewer, tighter bins instead of leaving mean-sized orphans everywhere.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        if pool < next_item_size as f64 {
            let deficit_frac = (next_item_size as f64 - pool) / next_item_size as f64;
            score -= 6.0 * deficit_frac * (1.0 - (dead - next_item_size as f64) / cap).clamp(0.0, 1.0)
                * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 47): dead-space ratio governor refinement — grade the
    // sub-half-dead band continuously so that among bins with similar
    // dead space, the one whose leftover is closest to a small-item
    // multiple is preferred, sharpening residual compaction.
    if post_residual > 0 && next_item_size > 0 && dead > 0.0 && dead < next_item_size as f64 * 0.5 {
        let small_unit = next_item_size.max(2) as f64 * 0.25;
        let near_tile = (dead / small_unit).round() * small_unit;
        let tile_gap = (dead - near_tile).abs() / small_unit.max(1.0);
        score -= 3.0 * (1.0 - tile_gap) * (0.3 + 0.7 * progress);
    }

    // MUTATION (gen 47): endgame fresh-bin suppression — in the final
    // stretch, opening a bin is almost never worth it unless the item is
    // huge and no open bin can host it; tighten the gate.
    if bin_residual == bin_capacity && progress > 0.8 && fitting_bins_count >= 1 {
        let big_frac = item_size as f64 / cap;
        if big_frac < 0.55 {
            score += 14.0 * (0.55 - big_frac) / 0.55 * (progress - 0.8) / 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        // MUTATION (gen 44): depth-2 lookahead — reward a residual that can
        // host the next item AND then still host a second copy or the item
        // size, i.e. a chain of closures.
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
        // MUTATION (gen 44): prefer the largest residual in the miss band.
        if gap <= 5 {
            score -= 2.0 * (5.0 - gap as f64) / 5.0 * (1.0 - progress);
        }
        // MUTATION (gen 44): near-miss rescue — a 1-2 unit miss is almost
        // recoverable elsewhere; sink such bins below wide misses.
        if gap <= 2 {
            score += 6.0 * (2.0 - gap as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                // MUTATION (gen 44): depth-2 fresh-bin tiling.
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        // MUTATION (gen 44): awkward-fit gate — when the fleet's mean
        // residual is within a couple units of the next item, open bins
        // are nearly usable; avoid spawning a fresh bin.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand
        // half of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
                // MUTATION (gen 44): exact two-step fresh closure, sharpened
                // by how far the fleet mean residual is from that target.
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Late-stream sliver hoarding relief.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // MUTATION (gen 44): residual-variance governor for fresh bins —
        // when the fresh remainder diverges from the fleet mean residual,
        // opening the bin worsens variance; reward the divergence relief.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    // Variance-collapse targeting — prefer placements whose resulting
    // residual sits closest to the current mean residual, shrinking
    // residual variance so future items tile the fleet uniformly.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-recovery steering — when the fleet's mean residual has
    // collapsed below the next item's size, reward placements whose
    // post-residual recovers toward a tileable band.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress));
    }

    // Compact-residual pull — when many bins compete, mildly prefer
    // leaving residuals just under the next item's size.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills of the bin's
    // residual, with escalation near closures.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
        // MUTATION (gen 44): shallow-fill anti-drift — penalize shallow
        // consumption that strands more than the next item's size when
        // many bins are open.
        if consume_ratio < 0.5 && post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size && open_bins_count >= 4 {
            let shallow = 1.0 - consume_ratio;
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5).max(0.0) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space salvage ranking — among bins that strand space below the
    // next item, prefer the one whose stranded remainder is closest to the
    // mean residual pool.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward when
    // the post-residual tiles with the next item.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
        // MUTATION (gen 44): harmonic depth pull — pull harder toward
        // multi-tile remainders so chains of next-item placements close.
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // MUTATION (gen 44): fleet-variance compaction — among fitting bins,
    // sharpen the pull toward the fleet mean residual so residual variance
    // collapses; the pull is quadratic in the deviation and ramps with
    // progress, but is suppressed when the deviation is a perfect next-item
    // tile (those remainders are valuable).
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 44): dead-space budget gate — estimate the fleet's
    // remaining item volume vs. remaining open-bin capacity; when the
    // slack margin is thin, penalize any placement that strands more than
    // the next item's size (waste prevention), and reward exact closures
    // proportionally harder as the margin tightens.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 44): cross-bin pair-closure lookahead — when the next
    // item cannot fit here, but the fleet's mean residual pool nearly
    // covers the missing amount, a cooperative split placement exists;
    // reward bins that leave the complementary share.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    score
}

