pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Smooth non-linear waste term: dead space penalized more when it cannot
    // plausibly host the lookahead item.
    if next_item_size > 0 && next_item_size as f64 > post {
        let gap = (next_item_size as f64 - post) / cap;
        score += 12.0 * gap * gap;
    }

    // Reward tight fits with a saturating non-linear bonus.
    score -= 25.0 * fit_ratio * fit_ratio / (1.0 + fit_ratio);

    // Late-stream pressure: prefer consolidating into open bins as stream ends,
    // penalize opening new bins increasingly with progress.
    let late = progress * progress;
    if is_new_bin {
        score += 30.0 * late + 5.0;
    } else {
        score -= 8.0 * late;
    }

    // Last-chance bin: strongly favor using it to avoid stranding capacity.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 + 15.0 * progress;
    }

    // Coupling with mean residual: if open bins are on average roomy, filling
    // them is cheap; if they are tight, avoid wasting their scarce space.
    let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score += 10.0 * tight * (post / cap) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into deciles of capacity.
    // Small post_residual classes are strongly rewarded (tight packing).
    let post_class = (post_residual.min(bin_capacity) * 10 / bin_capacity) as f64;
    score += post_class * post_class * 0.9; // quadratic penalty on coarse leftover class

    // Exact tight fits (post_residual in lowest classes) get a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily;
    // if next item cannot ever fit post_residual, the leftover is dead space -> penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // dead space for the known next item
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Modular arithmetic on post_residual: leftovers that are multiples of small
    // common sizes (e.g. multiples of 10/20) are more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0) {
        score -= 6.0;
    }
    // Odd, awkward leftovers (prime-like small residues) are penalized mildly.
    if post_residual > 0 && post_residual % 10 != 0 && post_residual < 15 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are tight.
    if bin_residual == bin_capacity {
        score += 12.0
            + mean_residual * 0.25
            + (open_bins_count as f64) * 0.8;
        // Late in the stream, be more reluctant to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    } else {
        // Prefer fuller bins among open ones: reward small bin_residual relative to mean.
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A small but non-zero post_residual is the worst outcome: it is "dead space"
    // that almost no future item (sizes 1..100) can use, yet it wastes the bin.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // strong penalty for unusable slivers
    }
    // Medium dead space (10..25) is only usable by small items; mildly penalize.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }
    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item fits exactly in the post_residual, this placement is excellent.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item fits within post_residual, mildly reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 8.0;
    }
    // If next item would leave yet another sliver, penalize the chain of dead space.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 15.0;
    }

    // --- Tight fit reward relative to bin residual ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // --- Open bins pressure ---
    // Too many open bins with scattered residuals: discourage spreading, encourage
    // consolidation into existing bins; opening a new bin should require need.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 5.0;
    // A new empty bin (residual == capacity) gets the pressure added so it is
    // only chosen when existing bins score poorly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += pressure + 6.0;
        // But if this item is a "last chance" nowhere else fits, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poor alternative.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Mean residual coupling ---
    // Placing into a bin whose residual is far below the mean consolidates
    // the "emptiest" bins elsewhere; reward filling below-mean bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // --- Stream progression: late in the stream, be more conservative ---
    // (prefer closing out bins cleanly rather than leaving slivers)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * progress; // extra late-stage sliver penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect match: next item exactly fills the post residual -> strongly reward.
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 40.0;
        } else if post >= nxt {
            // Next item fits: reward proportional to how snugly it fits.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            // Bonus if the two-item fill leaves near-zero dead space.
            let after2 = post - nxt;
            if after2 < 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item does NOT fit: penalize leaving unusable dead space
            // relative to the lookahead item.
            score += 12.0 * (1.0 - post / nxt.max(1.0) as f64);
        }
    }

    // Relative to mean residual: prefer bins whose post residual deviates
    // favorably (keeps portfolio of residuals diverse, near mean is fine).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_gap;

    // Last-chance bin: only bin that can fit this item -> strong reward.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only open if item is large or no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, reduced for large items.
        score += 35.0 - 0.25 * item_size as f64;
        // If few fitting bins and item is big, new bin becomes attractive.
        if fitting_bins_count <= 1 && item_size >= 50 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powf(4.0);

    // Penalize dead space: residuals too small for typical future items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can exactly fit the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial reward: next item still fits after this placement.
        score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize blocking the next item only mildly; residual may serve later items.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: discourage opening a new bin when open bins fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Early in the stream, opening bins is cheaper; later, consolidate aggressively.
        let new_bin_penalty = 20.0 + 60.0 * progress;
        score += new_bin_penalty;
        // If many bins are open and mean residual is high, opening new bins is wasteful.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 30.0;
        }
    }

    // Global pressure: when many bins are open relative to stream, tighten packing.
    let pressure = open_bins_count as f64 / (total_items as f64).max(1.0).sqrt();
    score += pressure * 3.0;

    // Prefer filling bins with larger residual (consolidate emptier bins less).
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Mean-residual alignment: favor bins whose post_residual matches mean residual
    // (keeps residuals homogeneous for future items).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Late-stream consolidation: as stream progresses, reward using existing bins harder.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 15.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 0.8 * progress) - 1.6 * pr_norm * pr_norm * (0.5 + progress)
        + 1.2 * pr_norm.powi(3) * (1.0 - progress);

    let mut score = pr + poly * cap;

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize waste relative to mean residual state
    score += 0.25 * (pr as f64 - mean_residual).max(0.0);

    // Lookahead: reward leaving space the next item can use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack).max(0.0) * (1.0 + 0.5 * progress);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening fresh bins early, penalize late
    if bin_residual == bin_capacity {
        score += 4.0 + 18.0 * progress + 0.5 * open_bins_count as f64;
        if pr_norm < 0.2 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: best-fit (minimize post_residual) with a mild tilt toward tight fits.
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (integer division thresholds) ---
    // Class 0: post_residual <= 5  -> near-perfect fit, strong reward.
    // Class 1: 6..=15              -> good fit, mild reward.
    // Class 2: 16..=30             -> mediocre, neutral.
    // Class 3: 31..=60             -> leaves a half-bin hole, penalize.
    // Class 4: >60                 -> bin barely used, heavy penalty.
    let cls = (post_residual / 15).min(4);
    score += match cls {
        0 => -8.0,
        1 => -3.0,
        2 => 0.0,
        3 => 4.0,
        _ => 10.0,
    };

    // --- Modulo arithmetic on post_residual vs. common small-item sizes ---
    // If the leftover space is exactly fillable by typical small item sizes
    // (mod 10 classes), the residual is "harmonic" and reusable.
    let harmonic = (post_residual % 10 == 0)
        || (post_residual % 20 == 0)
        || (post_residual % 25 == 0);
    if harmonic && post_residual > 0 {
        score -= 2.5;
    }

    // --- Lookahead coupling: can next_item_size exactly fill the gap? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chain: this bin absorbs both items
        } else if next_item_size <= post_residual {
            // Next item fits into the gap: reward proportionally to how
            // "snug" the future fit is (small post - next is good).
            let future_gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - future_gap / bin_capacity as f64);
        } else {
            // Next item will NOT fit in this bin's gap: if the gap is
            // awkwardly small (dead space), penalize.
            if post_residual < 10 {
                score += 3.0;
            }
        }
    } else {
        // Last item: waste is final; strongly prefer the tightest bin.
        score -= 5.0;
    }

    // --- Scarcity pressure: if this is the ONLY fitting bin, favor it ---
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost so it only wins when open bins
        // would create large dead space or when bins are scarce/early.
        score = bin_capacity as f64 * 0.9;
        if open_bins_count == 0 {
            score = -100.0; // must open the first bin
        } else if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin can host the next item too
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // --- Mean-residual context: if this bin is far below the mean residual,
    // it is already "dense"; using it is cheap. ---
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (super-linear in how "dead" the gap is).
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item almost fits (small miss), penalize slightly.
    if next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // Candidate is a brand-new bin: penalize more when many bins are open.
        score += 10.0 + 6.0 * pressure;
    } else {
        // Reward placing into existing bins, scaled by open-bin count.
        score -= 2.0 + 1.5 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer bins whose residual is below the mean (fill the emptiest-trending
    // bins first keeps mean residual low and closes bins out).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Mild global tightening over stream progress: waste matters more later.
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact or near-exact match of post_residual with next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_pair = post_residual - next_item_size;
        score -= 30.0 * (1.0 - slack_after_pair as f64 / bin_capacity as f64);
        if slack_after_pair == 0 {
            score -= 60.0; // perfect two-item fill
        }
    } else if next_item_size > 0 {
        // next item cannot follow: penalize residual that blocks it
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 15.0;
        }
    }

    // Penalize dead space relative to mean residual (worse than average bin)
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Prefer fuller bins overall (tight fit reward)
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Late in stream: be greedy, avoid opening new bins
    score += 10.0 * progress * (open_bins_count as f64 / (1.0 + open_bins_count as f64));

    // New-bin candidate: neutral baseline; open new bin only if all open fits are bad
    if bin_residual == bin_capacity {
        score = 55.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(6);

    // Penalize dead space: residuals that cannot fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: mild penalty for leaving a gap that strands it.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only bin that fits -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening new bins when open bins exist with decent mean residual.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += 15.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
        // If the item fills a new bin nearly perfectly, allow it.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 45.0 * fill.powi(3);
    }

    // Prefer filling bins that are already relatively full among open bins.
    if bin_residual < bin_capacity {
        let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * used_frac;
    }

    // Global pressure: many open bins -> encourage consolidation into emptier bins.
    if open_bins_count > 3 {
        let avg = mean_residual.max(1.0);
        let rel = bin_residual as f64 / avg;
        score += 8.0 * (rel - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Non-linear penalty on residual, stronger as stream progresses
    let x = pr / cap; // normalized post residual in [0,1]
    let w = 1.0 + progress * 2.0;
    score += w * 12.0 * x * x * (1.0 - x * 0.5);

    // Reward tight fits (small residual) with smooth exponential-ish coupling
    score -= (1.0 - x) * (1.0 - x) * (8.0 + 10.0 * progress);

    // Lookahead: bonus if next item fits exactly in post residual
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let nx = next_item_size as f64 / cap;
        score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap) * (1.0 - nx * 0.5);
    } else if next_item_size > 0 {
        // penalize residuals that cannot host the next item, scaled by progress
        score += 4.0 * progress * (1.0 - x);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly early, more when many bins already open and mean residual is small (poor packing so far)
    if bin_residual == bin_capacity {
        let mean_x = (mean_residual / cap).clamp(0.0, 1.0);
        let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
        score += 10.0 + 8.0 * open_pressure * (1.0 - mean_x) + 5.0 * progress * (1.0 - mean_x);
    }

    // Mild preference to fill bins with larger mean residual deviation
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot" of capacity it falls into.
    // Classes on capacity fractions (1/8 granularity): smaller class index = tighter fit.
    let class = (post_residual * 8 / bin_capacity) as f64;
    score += class * 1.7;

    // Integer-division thresholds on post_residual: dead space zones.
    // Residuals that no plausible item (1..=100, mean ~50) can fill are penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Perfect fit reward: post_residual matches a harmonic boundary.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Modulo coupling: does next item align with the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact chain fit
        } else if next_item_size <= post_residual {
            // next item fits: measure leftover harmony
            let chain_left = post_residual - next_item_size;
            if chain_left < 10 { score += 2.0; } else { score -= 5.0; }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Harmonic residue of next item size: quarter-capacity classes
        let nq = (next_item_size * 4 / bin_capacity.max(1)) as f64;
        score += nq * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Progress-aware pressure: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64) * 0.15;

    // Prefer bins below mean residual (concentrate fullness).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: neutral-ish baseline, penalize slightly unless open bins are terrible.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + class * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 5 && next_item_size <= bin_capacity {
            score -= 10.0; // reserve fresh bin for a big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item size
    // (1 unit interface, but practically anything below a usable threshold) are waste.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual closely matches the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size).min(20) as f64 * 0.5;
        } else {
            // next item cannot use the leftover -> dead space likely
            score += 15.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let worst_open_fit = (mean_residual - item_size as f64).abs();
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if worst_open_fit > 25.0 {
            score -= 10.0;
        } else {
            // an open bin fits acceptably; penalize opening a new one
            score += 45.0 + pressure * 2.0;
        }
    }

    // Mild attraction toward bins with residuals near the mean (keeps residual distribution tight)
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover (coupled lookahead reward)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.8;
    }
    // Next item would not fit here: mild penalty scaled to wasted lookahead potential
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize tiny unusable dead space (dead-space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward large usable residuals relative to mean
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.15;
    } else {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Early in stream: prefer opening new bins (keep flexibility); later: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 - 40.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Slight preference for filling fuller bins when many bins are open
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post-residual is small.
    let fit_ratio = post_residual as f64 / cap;
    score += 30.0 * fit_ratio * fit_ratio;

    // Perfect/near-perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item can use the post-residual exactly, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 8.0; // residual remains usable
        } else {
            score += 6.0; // residual too small for next item => dead space risk
            if post_residual < 10 {
                score += 8.0; // very small residual is nearly dead space
            }
        }
    } else {
        // Last item: any bin works, prefer fullest packing.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // New bin is attractive only if no open bin fits well.
        if post_residual == bin_capacity {
            // base new-bin score = 100 + 30*1 = 130; adjust:
            if fitting_bins_count == 0 {
                score -= 200.0; // nothing fits: must open
            } else {
                // penalize opening a new bin when alternatives exist,
                // unless existing bins have large residuals (poor fits)
                let poor_fits = (mean_residual - item_size as f64).abs() < 3.0;
                if poor_fits && open_bins_count > 0 {
                    score -= 120.0; // existing fits are bad; fresh bin is fine
                } else {
                    score += 45.0; // prefer placing into an existing open bin
                }
            }
        }
    } else {
        // Existing bin: mild bonus for using bins that are already open.
        score -= 3.0;
    }

    // Time horizon: early in the stream, keep bins flexible (avoid tiny residuals);
    // late in the stream, pack tightly at all costs.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * fit_ratio;
    score -= progress * 10.0 * fit_ratio;

    // Global state: many open bins with high mean residual => consolidate into open bins.
    if open_bins_count > 3 && mean_residual > 20.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Smooth non-linear coupling: residual normalized by capacity
    let x = pr / cap;

    // Base: post residual, with polynomial shaping that varies with progress
    let poly = x * (1.0 + progress * (1.0 - x) * 2.0) - progress * x * x;

    let mut score = pr * (1.0 + 0.5 * poly);

    // Penalize large post-residuals more strongly later in the stream
    score += 20.0 * progress * x * x * cap;

    // Reward tight fits (small post residual) with smooth exponential term
    score -= 15.0 * (-x * 6.0).exp() * (1.0 - progress * 0.5);

    // Lookahead coupling: smooth interaction of next item with remaining space
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        score += 8.0 * gap * gap * (1.0 - progress);
        score -= 5.0 * (x - nx) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 * (1.0 - progress * 0.3);
    }

    // Mild penalty for opening new bins when many are open and mean residual is high
    if is_new_bin {
        let mr = mean_residual / cap;
        score += 5.0 + 25.0 * mr * (1.0 - progress * 0.5) + 3.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Small tie-breaker noise-free smooth term
    score += 0.01 * (item_size as f64 / cap) * (progress - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which eighth of the capacity it occupies.
    let item_class = item_size / (bin_capacity / 8 + 1);
    let next_class = next_item_size / (bin_capacity / 8 + 1);

    // Complementary class pairs (sum to ~capacity): pair small-with-large.
    let comp = (item_class as f64 + next_class as f64 - 7.0).abs();
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: reward strong complementarity.
        score -= 6.0 * (7.0 - comp);
        score -= 4.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    } else if next_item_size > post_residual {
        // Next item does NOT fit after placing here: penalize, worse if post residual is tiny.
        score += 8.0 + 0.5 * next_item_size as f64;
    }

    // Dead-space penalty: post_residual in the "unusable" harmonic band.
    let unusable = (10..=30).contains(&post_residual);
    if unusable {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 10.0; // perfect closure
    } else if post_residual <= 9 {
        score -= 6.0; // near-perfect fill
    }

    // Integer-division threshold on post_residual: quantized fill level.
    let fill_quarter = post_residual / (bin_capacity / 4 + 1);
    score += fill_quarter as f64 * 3.0;

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer tightest residual among fitting bins when many options exist.
    if fitting_bins_count > 2 {
        score += (post_residual as f64 - mean_residual) * 0.4;
    }

    // New-bin candidate: make it attractive only when no open bin is a good harmonic match.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        let good_match_exists = next_item_size > 0 && open_bins_count > 0
            && (0..=post_residual).any(|_| false); // placeholder-free: use residual logic below
        let _ = good_match_exists;
        // Base cost of a new bin, discounted early in the stream or with few bins.
        score = 100.0 - 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64)
            - 5.0 * open_pressure;
        // If the item leaves a harmonically awkward gap in any bin, favor a fresh bin.
        if unusable {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            // Gap too small for any item (min size 1..100 stream, but typical
            // items are chunky) -> heavy penalty for wasting residual.
            score += 40.0;
        } else if post_residual <= 20 {
            // Small gap usable only by tiny items -> strong penalty.
            score += 18.0;
        } else if post_residual <= 35 {
            score += 6.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: fill ratio of the bin by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless the
    // new bin gives a much better residual.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to how many bins are open.
        score += 10.0 + 3.0 * open_bins_count as f64;
        // But if placing in an existing bin would leave tiny dead space,
        // opening fresh may be better; soften the penalty then.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward for consolidating load.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * chain_tightness;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (concentrate waste in fewer bins).
    let resid_dev = mean_residual - bin_residual as f64;
    score += 0.08 * resid_dev;

    // Stream progression: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual near 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain fit: residual consumed next step
        } else if next_item_size < post_residual {
            // next item fits, penalize proportional leftover after both placements
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            score -= 50.0 * (1.0 - two_step_leftover / bin_capacity as f64);
            score += 0.5 * two_step_leftover;
        } else {
            // next item cannot use this bin's residual: penalize dead space
            score += 0.3 * post_residual as f64;
            score += 20.0;
        }
    }

    // Compare residual against mean residual of open bins
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless residual is huge / fits poorly everywhere
    if bin_residual == bin_capacity {
        score += 250.0;
        // late in the stream, prefer compacting into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // if next item is large and no bin chains well, new bin slightly less bad
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 60.0;
        }
    }

    // Mild pressure to keep number of open bins low
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to zero is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Penalize dead space quadratically, but only if it is truly unusable
        // (smaller than the minimum plausible item).
        let dead = post_residual as f64;
        score += 0.15 * dead * dead / bin_capacity as f64;
        if post_residual < 10 {
            score += 20.0; // tiny sliver: wasted bin space
        }
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.1 * next_item_size as f64;
    }
    // Lookahead penalty: if next item cannot fit here but barely fits elsewhere,
    // this bin is less attractive.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score -= 2.0 * open_bins_count as f64 * 0.1;

    // Compare residual to the mean residual: bins below average residual
    // (already tight) are good targets; above-average bins keep flexibility.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate logic: only attractive when the item is large and
    // existing residuals are poor fits, or early in the stream with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Prefer new bin when item is big and open bins are fragmented.
        let new_bin_bias = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;
        score += new_bin_bias.max(-20.0).min(60.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Polynomial dead-space penalty: grows with progress (later items should leave less dead space)
    let poly = prn * prn * (1.0 + 2.0 * progress) + prn * prn * prn * (1.0 + 3.0 * prog2);
    score += 40.0 * poly;

    // Smooth interaction: reward tight fits more strongly as stream progresses
    let fit_quality = 1.0 - prn; // fraction of bin used
    score -= 30.0 * fit_quality * (0.5 + prog2) * (1.0 + 0.5 * prog3);

    // Lookahead coupling: smooth quadratic interaction between post_residual and next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            // next item could fit here: reward, scaled smoothly by closeness
            let closeness = 1.0 - (diff / bin_capacity as f64);
            score -= 15.0 * closeness * closeness * (1.0 + progress);
        } else {
            // next item won't fit: penalize proportionally to overshoot
            score += 0.05 * (-diff) * (1.0 + prog2);
        }
    }

