            let second_bonus = if two_step_leftover <= 2.0 { 18.0 }
                else if two_step_leftover as u32 == item_size { 12.0 }
                else if two_step_leftover as u32 == next_item_size { 8.0 } else { 0.0 };
            score -= (52.0 + chain_bonus + second_bonus) * (1.0 - two_step_leftover / cap);
