            // next item could chain twice into residual? soften if 2*next fits
            if 2 * next_item_size <= post_residual {
                score -= 8.0;
            }
        }
    }

    // Deviation from mean residual: reward tight bins nonlinearly
    let dev = post_residual as f64 - mean_residual;
