            }
            // Awkward mid-band dead space that next item can't use
            let rf = post_residual as f64 / cap;
            if rf > 0.55 && rf < 0.75 {
                score += 10.0 + 28.0 * (rf - 0.55);
            }
        }
        // Residual hosts both item and next item nearly exactly
        if post_residual >= item_size + next_item_size {
            let pair_slack = post_residual - (item_size + next_item_size);
            if pair_slack <= 3 {
                score -= 32.0 - 5.0 * pair_slack as f64;
            }
        }
        // Just-below-next-item trap
        if post_residual < next_item_size {
            let gap = next_item_size - post_residual;
            if gap <= 6 {
                score += 18.0 + 4.0 * (6 - gap) as f64;
            }
        }
    }

    // Deviation from mean residual
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.5 * dev;
    } else {
        score += 0.35 * dev + 0.05 * dev * dev / cap;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
