    }

    // Mild pressure to keep open bin count low
    score += 1.8 * open_bins_count as f64;

    // Waste ratio term
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
