            // Gap-proportional waste for near-misses on large next items.
            if gap > 0 && gap <= 25 && next_item_size >= bin_capacity / 4 {
                score += 0.25 * (25 - gap) as f64;
            }
            // MUTATION: scarcity-scaled near-miss — when only one other bin can
            // host the item, a near-miss here is doubly costly.
            if gap > 0 && gap <= 12 && fitting_bins_count == 1 {
                score += 0.9 * (12 - gap) as f64;
            }
