        if progress > 0.85 {
            penalty += 40.0;
        }
        if item_size as f64 >= 0.8 * cap {
            penalty += 60.0;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_left = post_residual.saturating_sub(next_item_size);
            if post_residual > next_item_size && worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        if item_size <= 6 && progress > 0.5 {
            penalty -= 25.0;
        }
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        if item_size >= bin_capacity / 2 && progress < 0.2 {
            penalty += 20.0;
        }
        // MUTATION: mean-residual gate — when the average leftover across open
        // bins is already large, a fresh bin keeps clean space; discount the
        // penalty proportionally to how bloated the mean is.
        if mean_residual > 0.35 * cap {
            penalty -= 45.0 * ((mean_residual - 0.35 * cap) / (0.4 * cap)).min(1.0);
        }
        // MUTATION: scarcity gate — with only one fitting bin, opening fresh
        // space is rarely better unless the fit is terrible.
        if fitting_bins_count <= 1 && post_residual as f64 <= 0.5 * cap {
            penalty += 35.0;
        }
        score += penalty;
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term: penalize residual as fraction of capacity nonlinearly
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }

    if post_residual >= 3 && post_residual <= 8 {
        score -= 6.0;
    }

    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    if post_residual == 2 * item_size {
        score -= 40.0;
    }
    if post_residual == 3 * item_size {
        score -= 18.0;
    }

    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
        // MUTATION: widened dead-space band — extend the awkward-residual
        // penalty down to 0.4 with a gentler slope to catch mid-band waste.
        if r >= 0.40 && r <= 0.55 {
            score += 5.0 + 25.0 * (r - 0.40);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum possible item size
    // (assumed ~1..10) are pure waste; penalize heavily the smaller they are.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Moderate penalty for gaps too small for the lookahead item but usable in general.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Near-perfect fit reward (residual within tiny usable margin).
    else if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills
    // (i.e., small post_residual already does this, add coupling).
    score += (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // New-bin candidate: only attractive when current item leaves a very awkward gap
    // in every open bin; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // reserve space for lookahead pairing
            score -= 10.0;
        }
    }

    // Stream progression: late in stream, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
