    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Near match: next item fits with small slack -> moderate reward.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 12.0 - (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit here: penalize small dead space (unusable gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: only fitting bin -> reward using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins below mean residual (tighter) preferred.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin early in the stream when open bins exist;
    // encourage consolidation when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
