        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Penalize dead space that is too small to be useful later (items >= 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here; mild bonus proportional to leftover
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item would need another bin; slight penalty scaled by waste
            score += 3.0;
        }
    }

