    // encourage consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0 * (0.5 + progress);
    }

    // Prefer bins whose residual is below mean (tighter bins) to keep loose bins
    // available for large future items.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.15;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only allow opening a new bin when the current item is large relative to
    // capacity and no tight fit exists; otherwise penalize the fresh bin.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 && fitting_bins_count <= 1 {
            score -= 10.0; // big item with no good home: fresh bin is fine
        } else {
            score += 20.0 + 10.0 * (1.0 - large_item); // discourage new bins otherwise
        }
    }

    score
}

