    let spread = (post_residual as f64 - mean_residual).abs();
    if spread < 0.05 * cap && post_residual > 0 {
        score -= 8.0;
    }

    // zero-waste sweep: residuals leaving exactly a common small fragment
    if post_residual >= 1 && post_residual <= 4 {
        score -= 12.0 - 2.0 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
