            // Adaptive chain depth — tighten tolerance when many bins fit.
            let tol = if fitting_bins_count >= 4 { 4.0 } else { 14.0 };
            if two_step_leftover > tol {
                score += 0.8 * (two_step_leftover - tol);
            }
            // Triple-chain lookahead — golden slot when item follows next exactly.
            if two_step_leftover as u32 == item_size {
                score -= 30.0;
            }
            // Dead-space after chain: unusable leftover is pure waste.
            let frac = two_step_leftover / cap;
            if frac < 0.08 && two_step_leftover > 0.0 {
                score -= 10.0 - 60.0 * frac;
            }
            // MUTATION: leftover usability bonus — if the two-step leftover can
            // still host the item itself, the chain continues; reward deeper.
            if two_step_leftover >= item_size as f64 && two_step_leftover <= 2.0 * item_size as f64 {
                score -= 12.0;
            }
        } else {
            score += 0.35 * post_residual as f64;
            if post_residual > 20 {
                score += 28.0;
            }
            if post_residual > 40 && next_item_size > post_residual + 30 {
                score += 18.0;
            }
            if post_residual < 10 && next_item_size <= 15 {
                score -= 10.0;
            }
            if post_residual >= bin_capacity / 4 && post_residual <= bin_capacity / 2 {
                score += 12.0;
