    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    // Harmonic-pair bonus — residual hosting item + item/2 is a prime slot.
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Dead-space ratio refinement — awkward 55–75% band the next item can't use.
    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
