        score += penalty;
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }

    if post_residual >= 3 && post_residual <= 8 {
        score -= 6.0;
    }

    // Fine-grained compaction
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    if post_residual == 2 * item_size {
        score -= 40.0;
    }
    if post_residual == 3 * item_size {
        score -= 18.0;
    }

    // Exact two-item packing potential
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    // Hard dead-space penalty for residuals just below the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space ratio guard
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragment-value guard
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    // Harmonic-pair bonus
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Awkward 55–75% dead-space band penalty
    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    // Residual-variance-aware tightness
    let spread = (post_residual as f64 - mean_residual).abs();
    if spread < 0.05 * cap && post_residual > 0 {
        score -= 8.0;
    }

    // zero-waste sweep — residuals leaving exactly a common small fragment
    if post_residual >= 1 && post_residual <= 4 {
        score -= 12.0 - 2.0 * post_residual as f64;
    }

    // MUTATION: dead-space ratio refinement — extra nonlinear penalty on
    // residuals in the awkward 55–75% band that the next item cannot use,
    // targeting the diagnosed dead-space weakness directly.
    if next_item_size > post_residual && post_residual > 0 {
        if r > 0.55 && r < 0.75 {
            score += 8.0 + 25.0 * (r - 0.55);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo structure on capacity fractions.
    // Residuals that are "harmonic" with common item sizes (multiples of 10/5)
    // are more reusable; penalize awkward classes.
    let pr = post_residual;
    let mod10 = (pr % 10) as f64;
    let mod5 = (pr % 5) as f64;

    // Penalize non-harmonic dead space quadratically.
    score += mod10 * mod10 * 0.15;
    score += mod5 * mod5 * 0.05;

    // Perfect fill is excellent.
    if pr == 0 {
        score -= 60.0;
    }

    // Small but usable residuals (< 10, min item size) are dead space: penalize hard.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Sweet-spot residuals: divisible by 10 and >= next item size -> reward.
    if mod10 == 0.0 && pr >= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let next_mod = (pr % next_item_size.max(1)) as f64;
            score -= 12.0 - next_mod * 0.4;
        } else {
            // Next item won't fit here; slight penalty unless residual is tiny.
            score += 4.0;
        }
    }

    // Last-chance bin (only fitting bin): avoid wasting it unless fill is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we prefer
    // reusing open bins, but it's attractive when all fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Cheaper to open new bins early in the stream or when many bins open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        score += (open_bins_count as f64).min(20.0) * 0.8;
        // If mean residual across open bins is large, reuse is fine; penalize new bin more.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 30.0;
        // If current item is large relative to capacity, new bin is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // If next item is large and won't fit after placing here anywhere, new bin helps.
        if next_item_size > pr && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Prefer tightest fills generally (post_residual already does this), plus
    // slight bonus for bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

