            // will strand its residual anyway.
            score += (diff.unsigned_abs() as f64).min(20.0) * 0.4;
        }
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones
    // (penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 25.0 + 6.0 * open_bins_count as f64;
    } else {
        // Reward using existing bins, scaled by how crowded the bin set is.
        score -= 2.0 + 0.5 * open_bins_count as f64;
    }

