    // Deviation from mean residual: nonlinear reward for tight bins.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.55 * dev;
    } else {
        score += 0.4 * dev + 0.06 * dev * dev / cap;
