        // MUTATION: fitting scarcity gate — when very few bins fit the item,
        // a fresh bin is far more expensive than it looks; stiffen penalty.
        if fitting_bins_count == 1 {
            penalty += 35.0;
        } else if fitting_bins_count == 2 {
