        // MUTATION: exact-fit scarcity — if the item exactly fills some
        // residual elsewhere (post_residual==0 on an open bin), never open.
        if next_item_size == 0 && item_size <= mean_residual as u32 {
            penalty += 20.0;
        }
        score += penalty;
    }

    // Mild pressure to keep open bin count low.
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term: nonlinear residual fraction penalty.
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
