            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    // MUTATION: global fragmentation balance — amplified compaction pressure
    // when open-bin count is high relative to progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
    }

    // MUTATION: exact next-item slot — residual exactly matching next item
    // after this placement is the strongest chain signal; extra reward when
    // bins are scarce.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual already does this; amplify it)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small-but-nonzero dead space that can never hold min-size items
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 15.0;
    }
    // Dead space that is small relative to typical future needs
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score += 6.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would fit better in a fresh bin, discourage consuming residual poorly
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 20.0;
        // More open bins => cheaper to consolidate instead of opening new
        score += 2.0 * open_bins_count as f64;
        // If many bins fit the item, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If next item is large, a fresh bin may serve it well
        if next_item_size > 0 && next_item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Slight preference for bins with larger residual when fitting (best-fit amplified)
    score += 0.05 * (bin_residual as f64);

    // Global residual pressure: if mean residual is low, use space efficiently
    score += 0.03 * mean_residual;

    score
}

