        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_left = post_residual.saturating_sub(next_item_size);
            if post_residual > next_item_size && worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        if item_size <= 6 && progress > 0.5 {
            penalty -= 25.0;
        }
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        if item_size >= bin_capacity / 2 && progress < 0.2 {
            penalty += 20.0;
        }
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        // MUTATION: scarcity gate — when only one bin fits, opening a fresh
        // bin is acceptable; soften the penalty to avoid forcing bad fits.
        if fitting_bins_count <= 1 {
            penalty -= 45.0;
        }
        // MUTATION: fragmentation counter-pressure — many open bins with
        // high mean residual means existing space is plentiful; stiffen.
        if open_bins_count as f64 > 4.0 + 8.0 * progress && mean_residual > 0.3 * cap {
            penalty += 30.0;
        }
        score += penalty;
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }

    if post_residual >= 3 && post_residual <= 8 {
        score -= 6.0;
    }

    // Fine-grained compaction
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    if post_residual == 3 * item_size {
        score -= 18.0;
    }

    // Exact two-item packing potential
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    // Hard dead-space penalty just below next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space ratio guard above half capacity
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragment-value guard
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    // Harmonic-pair bonus
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Awkward 55–75% band penalty
    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    // Global fragmentation balance
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
    }

    // MUTATION: leftover usability scan — small leftovers that could host
    // a fraction of the item are harvestable; punish truly dead leftovers.
    if next_item_size > 0 && next_item_size < post_residual {
        let lo = post_residual - next_item_size;
        if (item_size >= 6 && lo == item_size / 2) || (item_size >= 9 && lo == item_size / 3) {
            score -= 12.0;
        } else if lo < item_size / 3 && lo > 0 {
            score += 5.0 + 0.3 * (item_size as f64 - 3.0 * lo as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: residual worth decays with progress
    let decay = 1.0 - 0.5 * progress * progress;
    score -= 30.0 * pr_norm * (1.0 - pr_norm) * decay;

    // Penalize large dead space quadratically, scaled by stream progress
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: small post_residual with large fill ratio
    score -= 25.0 * fit_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (-gap * gap) * (1.0 - progress);
    } else {
        // last item: strongly favor minimizing residual
        score -= 15.0 * pr_norm;
    }

    // Last-chance bin bonus (smooth via fitting count)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm * pr_norm);
    }

    // Mean residual context: prefer bins near mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize mildly unless residuals are all poor
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 20.0 - 18.0 * scarcity - 10.0 * progress;
    }

    // Crowding pressure: fewer fitting bins -> favor using existing bins
    score -= 5.0 / (1.0 + fitting_bins_count as f64);

    score
}

