        }
        // Best-alternative quality gate.
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        // Early-stream large-item guard.
        if item_size >= bin_capacity / 2 && progress < 0.2 {
            penalty += 20.0;
        }
        // Mean-residual-aware gate.
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        // Two-item lookahead gate for fresh bins.
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // MUTATION (gen 15): fresh-bin residual reuse forecast — a new bin
        // opened now will hold this item and leave (cap - item) residual.
        // If that residual is a clean multiple of the item or next item
        // (tileable), the fresh bin is more valuable than it looks.
        if next_item_size > 0 {
            let fresh_res = bin_capacity.saturating_sub(item_size);
            let unit = next_item_size.max(1);
            if fresh_res % unit == 0 && fresh_res / unit >= 2 {
                penalty -= 30.0;
            } else if fresh_res > next_item_size && fresh_res < 2 * next_item_size {
                penalty += 18.0;
            }
