            let worst_left = post_residual.saturating_sub(next_item_size);
            if post_residual > next_item_size && worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        if item_size <= 6 && progress > 0.5 {
            penalty -= 25.0;
        }
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        if item_size >= bin_capacity / 2 && progress < 0.2 {
            penalty += 20.0;
        }
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // MUTATION (gen 15): best-alternative dead-space gate — compare the
        // fresh-bin leftover against the worst fitting-bin leftover; if the
        // fresh bin would strand strictly less space than any existing
        // option, opening it is structurally better. Scale the discount by
        // how much dead space the fresh bin avoids.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size {
            let existing_waste = post_residual - next_item_size;
            let fresh_waste = bin_capacity.saturating_sub(item_size);
            if fresh_waste < existing_waste {
