    // divisible by small common filler sizes (2,3,5) can be tiled by future
    // small items without stranding space; reward proportionally to the
    // divisor quality while avoiding double-counting with the entropy guard.
    if post_residual > 0 && post_residual < item_size {
        if post_residual % 5 == 0 {
            score -= 5.0;
        } else if post_residual % 3 == 0 {
            score -= 3.0;
        }
    }

    score
}

