        // Fresh bin attractive when every fitting bin leaves a large awkward leftover
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_left = post_residual.saturating_sub(next_item_size);
            if post_residual > next_item_size && worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        // Late-stream tiny items are cheap filler for fresh space
        if item_size <= 6 && progress > 0.5 {
            penalty -= 25.0;
        }
        // Best-alternative quality gate
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        // Mean-residual-aware gate
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        // Two-item lookahead gate for fresh bins
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // Early-stream large-item guard
        if item_size >= bin_capacity / 2 && progress < 0.2 {
            penalty += 20.0;
        }
        score += penalty;
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term: penalize residual as fraction of capacity nonlinearly
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }

    // Exact two-item multiple bonus
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }

    if post_residual >= 3 && post_residual <= 8 {
        score -= 6.0;
    }

    // Fine-grained compaction: near-exact fits scaled by slack
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    // Tighten selection pressure on the worst fits
    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    // Hard dead-space penalty for residuals just below the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    // Protect tight residuals when only two bins fit
    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space ratio guard: residual above half capacity is fragmentation risk
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragment-value guard
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    // Harmonic-pair bonus
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Awkward 55-75% band penalty
    if next_item_size > post_residual && r > 0.55 && r < 0.75 {
        score += 12.0 + 30.0 * (r - 0.55);
    }

    // Global fragmentation balance under high open-bin count
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard: prefer clean multiples of likely small fillers
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        let half = (item_size / 2).max(1);
        if pr % half == 0 && pr / half >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 16): scarcity-weighted perfect-fit escalation — when only
    // one or two bins can host the item, a zero/tiny post-residual is even
    // more precious; deepen the compaction reward to prevent near-misses.
    if fitting_bins_count <= 2 {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 4 {
            score -= 10.0 + 4.0 * (4 - post_residual) as f64;
        }
    }

    // MUTATION (gen 16): mid-band dead-space trap refinement — residuals in
    // the 30–50% band that the next item cannot use strand space that
    // typical stream items cannot fill; penalize proportionally, but
    // exempt residuals that already match the item's size class.
    if next_item_size > post_residual {
        let rm = post_residual as f64 / cap;
        if rm >= 0.30 && rm <= 0.50 && !(post_residual >= item_size && post_residual <= item_size + 8) {
            score += 9.0 + 22.0 * (rm - 0.30);
        }
    }

    // MUTATION (gen 16): fresh-bin two-item chain check — a new bin is
    // especially good if after this item AND the next item, the leftover
    // can still host a third copy of the item (deep chain potential).
    if bin_residual == bin_capacity && next_item_size > 0 {
        let first = item_size as u64 + next_item_size as u64;
        if first <= bin_capacity as u64 {
            let rem = bin_capacity as u64 - first;
            if rem >= item_size as u64 && rem - item_size as u64 <= 4 {
                penalty_free(&mut score, 30.0);
            }
        }
    }

    score
}

#[inline(always)]
fn penalty_free(score: &mut f64, amt: f64) {
    *score -= amt;
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
