pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 220.0;
    } else if post_residual == item_size {
        score -= 130.0;
    }

    // 2-step lookahead with refined coupling to next item size
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size < post_residual {
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            let chain_bonus = if next_item_size > bin_capacity / 2 { 25.0 } else { 0.0 };
            let second_bonus = if two_step_leftover <= 2.0 { 15.0 }
                else if two_step_leftover as u32 == item_size { 12.0 } else { 0.0 };
            score -= (50.0 + chain_bonus + second_bonus) * (1.0 - two_step_leftover / cap);
            score += 0.55 * two_step_leftover;
            if two_step_leftover >= 1.0 && two_step_leftover <= 12.0 {
                score -= 9.0;
            }
            if two_step_leftover as u32 >= item_size && item_size > 0 {
                let third_left = two_step_leftover as u32 - item_size;
                if third_left <= 3 {
                    score -= 20.0 - 4.0 * third_left as f64;
                }
            }
            // Chain depth weighting — deeper chains worth more when next item is large.
            if next_item_size >= bin_capacity / 3 && two_step_leftover <= 6.0 {
                score -= 14.0;
            }
            // Adaptive chain depth — when many bins can host the item,
            // chains are less scarce; tighten the leftover tolerance instead.
            let tol = if fitting_bins_count >= 4 { 4.0 } else { 14.0 };
            if two_step_leftover > tol {
                score += 0.8 * (two_step_leftover - tol);
            }
            // Triple-chain lookahead — if the item itself can follow
            // the next item exactly, this bin is a golden slot.
            if two_step_leftover as u32 == item_size {
                score -= 30.0;
            }
            // Dead-space after chain: leftover that nothing can use is pure waste.
            let frac = two_step_leftover / cap;
            if frac < 0.08 && two_step_leftover > 0.0 {
                score -= 10.0 - 60.0 * frac;
            }
            // Leftover usability scan — small leftovers that could host a
            // scaled-down version of the item (item/2, item/3) are still
            // harvestable; reward those, punish truly dead leftovers.
            if two_step_leftover > 0.0 {
                let lo = two_step_leftover as u32;
                if (item_size >= 6 && lo == item_size / 2)
                    || (item_size >= 9 && lo == item_size / 3) {
                    score -= 12.0;
                } else if lo < item_size / 3 && lo > 0 {
                    score += 5.0 + 0.3 * (item_size as f64 - 3.0 * lo as f64);
                }
            }
            // Dead-space ratio refinement on the chained leftover.
            if two_step_leftover > 0.0 {
                let lof = two_step_leftover as u32;
                let min_fill = (item_size / 4).max(1);
                if lof < item_size && lof >= 2 * min_fill {
                    score += 4.0 + 0.5 * (item_size - lof) as f64;
                }
            }
            // MUTATION (gen 16): chain scarcity amplification — when the
            // next item can only chain in very few bins, completing the
            // chain here is extra valuable; scale reward by scarcity.
            if fitting_bins_count <= 3 && two_step_leftover <= 10.0 {
                score -= 6.0 + 2.0 * (3 - fitting_bins_count.min(3)) as f64
                    * (1.0 - two_step_leftover / 10.0);
            }
        } else {
            score += 0.35 * post_residual as f64;
            if post_residual > 20 {
                score += 28.0;
            }
            if post_residual > 40 && next_item_size > post_residual + 30 {
                score += 18.0;
            }
            if post_residual < 10 && next_item_size <= 15 {
                score -= 10.0;
            }
            if post_residual >= bin_capacity / 4 && post_residual <= bin_capacity / 2 {
                score += 12.0;
            }
            // Soft-dead-space trap — residual can't host next item in the mid-band.
            let gap = next_item_size - post_residual;
            if gap <= 10 && post_residual > 8 {
                score += 6.0 + 1.2 * gap as f64;
            }
            // Scarcity-aware trap — if few bins fit, an unusable residual
            // here forces a new bin later; escalate the penalty.
            if gap <= 16 && post_residual > 12 && fitting_bins_count <= 2 {
                score += 10.0 + 0.9 * gap as f64;
            }
            // Gap-proportional waste — larger unusable gaps are worse
            // when the gap is small relative to the next item (near-miss pain).
            if gap > 0 && gap <= 25 && next_item_size >= bin_capacity / 4 {
                score += 0.25 * (25 - gap) as f64;
            }
            // Scarcity-amplified near-miss — when almost no other
            // bin can host this item, a near-miss residual is doubly costly
            // because the item will likely land here and strand the gap.
            if gap > 0 && gap <= 8 && fitting_bins_count <= 2 {
                score += 8.0 + 2.0 * (8 - gap) as f64;
            }
            // Near-miss lookahead guard — when the gap is moderate and the
            // next item itself would leave a tiny leftover after this bin,
            // the stranded space compounds; scale penalty by the implied
            // second-level waste.
            if gap > 8 && gap <= 20 && post_residual + next_item_size <= bin_capacity {
                let implied_waste = bin_capacity - post_residual - next_item_size;
                if implied_waste <= 4 {
                    score += 5.0 + 1.5 * (4 - implied_waste) as f64;
                }
            }
            // MUTATION (gen 16): mean-residual coupling on the trap branch —
            // when the fleet-wide average leftover is already tight, wasting
            // space here is costlier because there is less slack elsewhere
            // to absorb the stranded gap.
            if gap > 0 && gap <= 14 && mean_residual < 0.25 * cap {
                score += 4.0 + 0.6 * (14 - gap) as f64 * (1.0 - mean_residual / (0.25 * cap));
            }
        }
    }

    // Deviation from mean residual: reward tight bins nonlinearly
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.55 * dev;
    } else {
        score += 0.4 * dev + 0.06 * dev * dev / cap;
    }

    // Last-chance bin: avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 160.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 260.0 + 110.0 * progress;
        if item_size > bin_capacity / 2 {
            penalty -= 90.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 45.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_capacity / 2 {
            penalty -= 70.0;
        }
        if progress > 0.7 && open_bins_count > 10 {
            penalty += 55.0;
        }
        if item_size <= 10 && progress < 0.3 {
            penalty += 30.0;
        }
        if progress > 0.85 {
            penalty += 40.0;
        }
        if item_size as f64 >= 0.8 * cap {
            penalty += 60.0;
        }
        // Fresh-bin attractive when every fitting bin leaves a large awkward leftover.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_left = post_residual.saturating_sub(next_item_size);
            if post_residual > next_item_size && worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        // Late-stream small items — opening a bin early in the stream
        // wastes capacity; late, tiny items are cheap filler for fresh space.
        if item_size <= 6 && progress > 0.5 {
            penalty -= 25.0;
        }
        // Best-alternative quality gate — when the best fitting bin
        // still wastes more than 60% of its residual, a fresh bin is often
        // better; discount the new-bin penalty in that case.
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        // Early-stream large-item guard — big items early should
        // strongly prefer filling existing space before opening fresh bins.
        if item_size >= bin_capacity / 2 && progress < 0.2 {
            penalty += 20.0;
        }
        // Mean-residual-aware gate — when the average leftover
        // across open bins is already large, squeezing this item into an
        // existing bin is comparatively cheap; stiffen the new-bin penalty.
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        // Two-item lookahead gate for fresh bins — a brand-new bin is only
        // worth opening if the item plus the next item leaves reasonable
        // space; if item+next nearly fills a fresh bin exactly, opening is
        // cheap (discount), otherwise stiffen.
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // MUTATION (gen 16): residual-quality gate on fresh bins — compare
        // the fresh-bin post-residual (capacity - item) against the best
        // existing alternative; if the fresh bin would leave LESS dead
        // space than the best open bin, opening is justified.
        if fitting_bins_count >= 1 {
            let fresh_left = bin_capacity - item_size;
            if (fresh_left as f64) < 0.55 * post_residual as f64 && fresh_left <= 8 {
                penalty -= 50.0;
            } else if fresh_left as f64 > 1.4 * post_residual as f64 {
                penalty += 20.0;
            }
        }
        // MUTATION (gen 16): fragmentation-phase coupling — early in the
        // stream with few open bins, keep the fleet tight; late with many
        // bins, a fresh bin acts as a clean consolidation target.
        if open_bins_count <= 3 && progress < 0.25 {
            penalty += 35.0;
        } else if progress > 0.6 && open_bins_count >= 6 && item_size >= bin_capacity / 3 {
            penalty -= 20.0;
        }
        score += penalty;
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term: penalize residual as fraction of capacity nonlinearly
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }

    if post_residual >= 3 && post_residual <= 8 {
        score -= 6.0;
    }

    // Fine-grained compaction — reward near-exact fits, scaled by tightness
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    // Tighten selection pressure on the worst fits
    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    // Self-similar residual chain — residual exactly matching item multiples
    if post_residual == 2 * item_size {
        score -= 40.0;
    }
    if post_residual == 3 * item_size {
        score -= 18.0;
    }

    // Exact two-item packing potential — residual fits item + next item
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    // Hard dead-space penalty for residuals just below the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    // When very few bins fit, protect tight residuals from loose alternatives
    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space ratio guard — post-residual above half capacity is a
    // fragmentation risk unless it can host the next item too.
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching — prefer bins whose residual is in the same
    // size class as the item.
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragment-value guard — small post-residual that next item can't use.
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    // Harmonic-pair bonus — residual that exactly hosts item plus a
    // plausible small remainder (item/2) is a prime two-item slot.
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Dead-space ratio refinement — extra nonlinear penalty on
    // residuals in the awkward 55–75% band that the next item cannot use.
    if next_item_size > post_residual {
        let rf = r;
        if rf > 0.55 && rf < 0.75 {
            score += 12.0 + 30.0 * (rf - 0.55);
        }
    }

    // Global fragmentation balance — when open-bin count is high
    // relative to stream progress, amplify the reward for zero/low post
    // residuals to force compaction into existing space instead of
    // spreading items thinly across many partially-filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        // Scarcity-weighted compaction — under high fragmentation, bins
        // that can still host the NEXT item are precious multi-use slots;
        // reward them further.
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard — prefer residuals that are "clean multiples"
    // of likely small fillers (item/2, item/3, item/4) over arbitrary
    // mid-sized leftovers; exact divisibility means the residual can be
    // tiled without stranding space.
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        if pr % (item_size / 2).max(1) == 0 && pr / (item_size / 2).max(1) >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 16): three-item fill potential — residual that can
    // host item + next + a small third filler (next/2) is a high-value
    // triple slot; reward it to squeeze the last units out of residuals.
    if next_item_size > 0 && next_item_size >= 4 && post_residual >= item_size + next_item_size + next_item_size / 2 {
        let triple_slack = post_residual - (item_size + next_item_size + next_item_size / 2);
        if triple_slack <= 2 {
            score -= 22.0 - 6.0 * triple_slack as f64;
        }
    }

    score
}

