        score -= 18.0;
    }

    // Exact two-item packing potential
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    // Hard dead-space penalty for residuals just below the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space ratio guard above half capacity
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragment-value guard
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    // Harmonic-pair bonus
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Dead-space ratio refinement in the awkward 55–75% band
    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    // Global fragmentation balance under high open-bin count
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard — clean multiples tile without stranding.
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        if pr % (item_size / 2).max(1) == 0 && pr / (item_size / 2).max(1) >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 17): mean-residual compaction pull — when a bin's
    // post-residual sits well below the fleet average, it is a scarce
    // tight slot; deepen the reward proportionally to the shortfall and
    // to how fragmented the fleet already is.
    if post_residual > 0 {
        let shortfall = mean_residual - post_residual as f64;
        if shortfall > 0.0 && open_bins_count > 3 {
            score -= (1.5 + 0.02 * open_bins_count as f64) * shortfall.min(30.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong rewards for exact / near-exact fills (borrowed from best-known).
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    } else if post_residual == item_size {
        score -= 110.0;
    } else {
        // Quadratic dead-space penalty for unusable leftovers.
        let dead = post_residual as f64;
        score += 0.15 * dead * dead / cap;
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // with a chain-depth refinement on the two-step leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            score -= (40.0 + 0.1 * next_item_size as f64) * (1.0 - two_step_leftover / cap);
            score += 0.5 * two_step_leftover;
            if two_step_leftover <= 6.0 {
                score -= 12.0;
            }
            // Triple-chain: leftover exactly matches the item again.
            if two_step_leftover as u32 == item_size {
                score -= 30.0;
            }
            // Adaptive tolerance: when many bins fit, chains are less scarce.
            let tol = if fitting_bins_count >= 4 { 5.0 } else { 14.0 };
            if two_step_leftover > tol {
                score += 0.8 * (two_step_leftover - tol);
            }
        } else {
            // Next item cannot fit here — near-miss penalties scaled by gap
            // and by scarcity of alternative bins.
            let gap = next_item_size - post_residual;
            score += 0.35 * post_residual as f64;
            if gap <= 10 && post_residual > 8 {
                score += 6.0 + 1.2 * gap as f64;
            }
            if gap <= 16 && post_residual > 12 && fitting_bins_count <= 2 {
                score += 10.0 + 0.9 * gap as f64;
            }
            if post_residual < 10 && next_item_size <= 15 {
                score -= 10.0;
            }
        }
    }

    // Deviation from mean residual: reward tight bins nonlinearly.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.55 * dev;
    } else {
        score += 0.4 * dev + 0.06 * dev * dev / cap;
    }

    // Last-chance bonus: only fitting bin — strongly avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 140.0;
    }

    // Mild consolidation pressure with many open bins.
    score += 0.2 * open_bins_count as f64;

    // New-bin candidate handling with a calibrated gate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 240.0 + 100.0 * progress;
        if item_size > bin_capacity / 2 {
            penalty -= 80.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 45.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_capacity / 2 {
            penalty -= 60.0;
        }
        if progress > 0.7 && open_bins_count > 10 {
            penalty += 50.0;
        }
        if item_size as f64 >= 0.8 * cap {
            penalty += 55.0;
        }
        // Fresh bin attractive when the best fitting bin would strand a
        // large awkward leftover.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_left = post_residual.saturating_sub(next_item_size);
            if post_residual > next_item_size && worst_left > bin_capacity / 3 {
                penalty -= 50.0;
            }
        }
        // Two-item lookahead gate: item + next nearly filling a fresh bin
        // makes opening cheap; a half-empty fresh bin is wasteful.
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // Mean-residual-aware gate: large average leftovers mean existing
        // bins are roomy — stiffen the new-bin penalty.
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        score += penalty;
    }

    // Waste-ratio term: nonlinear penalty on residual fraction.
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 12.0;
    }

    // Fine-grained compaction — reward near-exact fits.
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    // Tighten selection pressure on the worst fits.
    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    // Self-similar residual chain — residual matches item multiples.
    if post_residual == 2 * item_size {
        score -= 40.0;
    }
    if post_residual == 3 * item_size {
        score -= 18.0;
    }

    // Exact two-item packing potential — residual fits item + next item.
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    // Hard dead-space penalty for residuals just below the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    // Protect tight residuals when only two bins fit.
    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // Fragmentation guard: post-residual above half capacity is risky
    // unless it can host the next item too.
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching — prefer residuals in the item's size class.
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragment-value guard — small post-residual the next item can't use.
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    // Harmonic-pair bonus — residual hosts item plus item/2.
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Awkward 55–75% band penalty when next item can't use it.
    if next_item_size > post_residual && r > 0.55 && r < 0.75 {
        score += 12.0 + 30.0 * (r - 0.55);
    }

    // Global fragmentation balance — amplify compaction under high
    // fragmentation relative to stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard — prefer clean multiples of item/2 as leftovers.
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        let half = (item_size / 2).max(1);
        if pr % half == 0 && pr / half >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 17): dual-fit bonus — a bin whose post-residual can
    // host BOTH the next item and a scaled copy of the current item is a
    // prime multi-use slot; reward proportionally to how cleanly it tiles.
    if next_item_size > 0 && post_residual >= next_item_size + item_size / 2 {
        let after_next = post_residual - next_item_size;
        if after_next >= item_size / 2 && after_next <= item_size {
            score -= 10.0 + 0.2 * (item_size - after_next) as f64;
        }
    }

    // MUTATION (gen 17): late-stream tightness escalation — near the end
    // of the stream, stranded residuals are almost pure waste since few
    // items remain to fill them; sharpen penalties on mid-sized leftovers.
    if progress > 0.8 && post_residual > 4 && post_residual < item_size {
        score += 6.0 + 0.3 * (item_size - post_residual) as f64;
    }

    score
}

