    // Modulo class coupling: does next_item_size divide nicely into the residual?
    if next_item_size > 0 && (pr as u64) >= (next_item_size as u64) {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 30.0; // lookahead exactly closes this bin
        } else if gap <= eighth {
            score -= 10.0; // lookahead leaves tiny dead space
        } else {
            // harmonic divisibility: residual divisible into next_item-sized chunks
            if next_item_size > 0 && pr % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
            score += gap as f64 * 0.15; // penalize leftover beyond lookahead
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: residual is stranded relative to lookahead
        score += (next_item_size - pr) as f64 * 0.1;
    }

    // New-bin candidate handling: empty bin gets baseline pull toward reuse of open bins.
    if bin_residual == bin_capacity {
        // opening a new bin is fine early or when nothing fits well elsewhere
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        // default: slightly discourage new bins so tight fits win
        score += 18.0 - 10.0 * progress - scarcity;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    } else if fitting_bins_count == 1 {
        // last-chance bin: strongly favor using it
        score -= 15.0;
    }

    // Mean-residual context: if this bin is unusually full vs. fleet, prefer filling it.
    let resid = bin_residual as f64;
    if resid + 0.5 < mean_residual {
        score -= (mean_residual - resid) * 0.2;
    } else {
        score += (resid - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 220.0;
    } else if post_residual == item_size {
        score -= 130.0;
    }

    // 2-step lookahead with refined couplings
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size < post_residual {
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            let chain_bonus = if next_item_size > bin_capacity / 2 { 25.0 } else { 0.0 };
            let second_bonus = if two_step_leftover <= 2.0 { 15.0 }
                else if two_step_leftover as u32 == item_size { 12.0 } else { 0.0 };
            score -= (50.0 + chain_bonus + second_bonus) * (1.0 - two_step_leftover / cap);
            score += 0.55 * two_step_leftover;
            if two_step_leftover >= 1.0 && two_step_leftover <= 12.0 {
                score -= 9.0;
            }
            if two_step_leftover as u32 >= item_size && item_size > 0 {
                let third_left = two_step_leftover as u32 - item_size;
                if third_left <= 3 {
                    score -= 20.0 - 4.0 * third_left as f64;
                }
            }
            if next_item_size >= bin_capacity / 3 && two_step_leftover <= 6.0 {
                score -= 14.0;
            }
            let tol = if fitting_bins_count >= 4 { 4.0 } else { 14.0 };
            if two_step_leftover > tol {
                score += 0.8 * (two_step_leftover - tol);
            }
            if two_step_leftover as u32 == item_size {
                score -= 30.0;
            }
            let frac = two_step_leftover / cap;
            if frac < 0.08 && two_step_leftover > 0.0 {
                score -= 10.0 - 60.0 * frac;
            }
            if two_step_leftover > 0.0 {
                let lo = two_step_leftover as u32;
                if (item_size >= 6 && lo == item_size / 2)
                    || (item_size >= 9 && lo == item_size / 3) {
                    score -= 12.0;
                } else if lo < item_size / 3 && lo > 0 {
                    score += 5.0 + 0.3 * (item_size as f64 - 3.0 * lo as f64);
                }
            }
            if two_step_leftover > 0.0 {
                let lof = two_step_leftover as u32;
                let min_fill = (item_size / 4).max(1);
                if lof < item_size && lof >= 2 * min_fill {
                    score += 4.0 + 0.5 * (item_size - lof) as f64;
                }
            }
            // MUTATION (gen 18): chain-continuation scan — if the chained
            // leftover can still host the item itself (a third item lands
            // here), this bin is a triple-fill slot; reward proportionally
            // to how tightly the third item fits.
            if two_step_leftover as u32 >= item_size && item_size > 0 {
                let third_gap = two_step_leftover as u32 - item_size;
                if third_gap <= 8 {
                    score -= 10.0 + 1.5 * (8 - third_gap) as f64;
                }
            }
        } else {
            score += 0.35 * post_residual as f64;
            if post_residual > 20 {
                score += 28.0;
            }
            if post_residual > 40 && next_item_size > post_residual + 30 {
                score += 18.0;
            }
            if post_residual < 10 && next_item_size <= 15 {
                score -= 10.0;
            }
            if post_residual >= bin_capacity / 4 && post_residual <= bin_capacity / 2 {
                score += 12.0;
            }
            let gap = next_item_size - post_residual;
            if gap <= 10 && post_residual > 8 {
                score += 6.0 + 1.2 * gap as f64;
            }
            if gap <= 16 && post_residual > 12 && fitting_bins_count <= 2 {
                score += 10.0 + 0.9 * gap as f64;
            }
            if gap > 0 && gap <= 25 && next_item_size >= bin_capacity / 4 {
                score += 0.25 * (25 - gap) as f64;
            }
            if gap > 0 && gap <= 8 && fitting_bins_count <= 2 {
                score += 8.0 + 2.0 * (8 - gap) as f64;
            }
            if gap > 8 && gap <= 20 && post_residual + next_item_size <= bin_capacity {
                let implied_waste = bin_capacity - post_residual - next_item_size;
                if implied_waste <= 4 {
                    score += 5.0 + 1.5 * (4 - implied_waste) as f64;
                }
            }
            // MUTATION (gen 18): scarcity-tiered near-miss — the cost of a
            // near-miss gap scales with how many other bins could take the
            // item; with exactly one alternative the penalty is doubled.
            if gap > 0 && gap <= 6 {
                let scarcity = match fitting_bins_count {
                    0 => 2.0,
                    1 => 1.6,
                    2 => 1.2,
                    _ => 0.8,
                };
                score += scarcity * (3.0 + 1.0 * (6 - gap) as f64);
            }
