        // bin would host this item AND the next item with a leftover that
        // is a clean multiple of the item (tilable), opening is cheap;
        // an untileable large leftover stiffens the penalty instead.
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair <= bin_capacity as u64 {
                let fresh_left = bin_capacity - pair as u32;
                if fresh_left > 0 {
