            let mismatch = (pr - nx).abs() / bin_capacity as f64;
            score += mismatch * 60.0;

            // Reward if next item still fits in the residual (soft chain),
            // scaled by how snugly it fits.
            if next_item_size <= post_residual {
                let snug = (post_residual - next_item_size) as f64 / bin_capacity as f64;
                score -= 40.0 * (1.0 - snug);
            } else {
                // Next item won't fit: residual risks becoming dead space,
                // penalize proportionally to wasted space relative to mean residual.
                score += (pr - mean_residual).abs() * 0.5;
            }
        }

        // Also check chain where next item alone fills residual exactly
        // (already covered by exact match above).
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // nearly full; prefer placing into them to close bins out.
    let rel = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += rel * 35.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current placement would be terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduce if item is large (efficient fill)
