        if post_residual > 0 && post_residual < 10 {
            score -= 30.0; // nearly perfect fill of fresh bin is great
        }
    }

    // Slight preference for filling bins earlier in stream (keeps options open later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

