            penalty += 55.0;
        }
        if item_size <= 10 && progress < 0.3 {
            penalty += 30.0;
        }
        if progress > 0.85 {
            penalty += 40.0;
        }
        if item_size as f64 >= 0.8 * cap {
            penalty += 60.0;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_left = post_residual.saturating_sub(next_item_size);
            if post_residual > next_item_size && worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        if item_size <= 6 && progress > 0.5 {
            penalty -= 25.0;
        }
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        if item_size >= bin_capacity / 2 && progress < 0.2 {
            penalty += 20.0;
        }
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // MUTATION (gen 19): fresh-bin scarcity gate — when very few bins
        // can host the item and the best existing fit is a near-miss
        // (gap to next item small), a fresh bin is comparatively cheap.
        if fitting_bins_count <= 2 && next_item_size > post_residual {
            let gap = next_item_size - post_residual;
            if gap <= 6 {
                penalty -= 30.0 + 4.0 * (6 - gap) as f64;
            }
        }
        score += penalty;
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term: nonlinear residual penalty
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }

    if post_residual >= 3 && post_residual <= 8 {
        score -= 6.0;
    }

    // Fine-grained compaction — reward near-exact fits
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    // Self-similar residual chain
    if post_residual == 2 * item_size {
        score -= 40.0;
    }
    if post_residual == 3 * item_size {
        score -= 18.0;
    }

    // Exact two-item packing potential
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    // Hard dead-space penalty for residuals just below the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space ratio guard above half capacity
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragment-value guard
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    // Harmonic-pair bonus
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Awkward 55–75% band penalty
    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    // Global fragmentation balance
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard — tileable residuals preferred
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        if pr % (item_size / 2).max(1) == 0 && pr / (item_size / 2).max(1) >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 19): late-stream tightness escalation — near the end
    // of the stream, residual waste is nearly irrecoverable, so tighten
    // selection pressure proportionally to remaining-item density.
    if progress > 0.75 && post_residual > 0 {
        let tail = (progress - 0.75) / 0.25;
        if post_residual < item_size {
            score += 4.0 * tail;
        } else if post_residual <= item_size + 2 {
            score -= 3.0 * tail;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a residual that the next item cannot use
    // (dead space), reward residuals that exactly or nearly fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 45.0; // next item nests perfectly
            } else {
                score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // residual too small for next item: dead space penalty grows
            // with how close the next item is to filling a fresh bin.
            let waste = post_residual as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are fragmented (high mean residual) or this is a very
    // poor fit. Make the fresh-bin option expensive by default.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If mean residual across open bins is small (bins well-packed),
        // opening a new bin becomes more acceptable.
        score -= 1.2 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If many bins can fit the item, definitely avoid a new bin.
        score += 8.0 * (fitting_bins_count as f64);
    }

    // Mild penalty on very large leftover gaps that nothing (10..80) can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny residual is nearly a perfect fit
    }
    if post_residual > 80 {
        score += 5.0; // large gap still usable, but less urgent to fill now
    }

    // Encourage balancing residual usage: prefer bins below mean residual
    // (more room left) slightly when bins are scarce.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
