            score += 8.0 + 40.0 * waste_frac;
        }
    }

    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    // Global fragmentation balance
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard — clean multiples of item/2 tile without waste
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        if pr % (item_size / 2).max(1) == 0 && pr / (item_size / 2).max(1) >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 19): dead-space ratio closure — residuals in the
    // awkward band just below the smallest usable filler (item/2) are
    // near-certainly dead once the next item lands elsewhere; penalize
    // them in proportion to how far below the filler threshold they sit,
    // but only when alternative bins exist (scarcity-aware).
    if post_residual > 0 && item_size >= 8 && fitting_bins_count >= 2 {
        let half = item_size / 2;
        if post_residual < half && post_residual > half / 2 {
            let depth = (half - post_residual) as f64;
            score += 3.0 + 0.6 * depth;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 18.0 * pr_norm * pr_norm * (1.0 - progress);
    score -= 25.0 * pr_norm * (p2 + 0.5 * p3);

    // Reward tight fits more aggressively as stream advances (smooth cubic in progress)
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead coupling: penalize post-residual that cannot fit next item, smoothly
    if next_item_size > 0 {
        let usable = (pr_norm - next_norm).max(0.0);
        score += 12.0 * (pr_norm - next_norm - usable) * (1.0 + progress);
        score -= 8.0 * usable * usable;
    }

    // Last-chance bin: smooth exponential-like urgency scaled by progress
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress * progress);
    }

    // Penalize bins far from mean residual (non-linear dispersion term)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for opening new bins early; grows as more bins exist
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

