                if third_left <= 3 {
                    score -= 20.0 - 4.0 * third_left as f64;
                }
            }
            if next_item_size >= bin_capacity / 3 && two_step_leftover <= 6.0 {
                score -= 14.0;
            }
            let tol = if fitting_bins_count >= 4 { 4.0 } else { 14.0 };
            if two_step_leftover > tol {
                score += 0.8 * (two_step_leftover - tol);
            }
            if two_step_leftover as u32 == item_size {
                score -= 30.0;
            }
            let frac = two_step_leftover / cap;
            if frac < 0.08 && two_step_leftover > 0.0 {
                score -= 10.0 - 60.0 * frac;
            }
            // Leftover usability scan — harvestable fractional leftovers.
            if two_step_leftover > 0.0 {
                let lo = two_step_leftover as u32;
                if (item_size >= 6 && lo == item_size / 2)
                    || (item_size >= 9 && lo == item_size / 3) {
                    score -= 12.0;
                } else if lo < item_size / 3 && lo > 0 {
                    score += 5.0 + 0.3 * (item_size as f64 - 3.0 * lo as f64);
                }
            }
            // Dead-space ratio refinement on chained leftover.
            if two_step_leftover > 0.0 {
                let lof = two_step_leftover as u32;
                let min_fill = (item_size / 4).max(1);
                if lof < item_size && lof >= 2 * min_fill {
                    score += 4.0 + 0.5 * (item_size - lof) as f64;
                }
            }
            // MUTATION (gen 19): chain-continuation viability — if the chained
            // leftover can still host a fraction (item/2) of the item, the bin
            // remains productive; otherwise the chain terminates in dead space.
            if two_step_leftover > 0.0 {
                let lo = two_step_leftover as u32;
                let half = (item_size / 2).max(1);
                if lo >= half && lo < item_size {
                    score -= 6.0 + 0.2 * (item_size - lo) as f64;
                } else if lo > 0 && lo < half {
                    // Dead-chain end: escalate when few alternatives exist.
                    if fitting_bins_count <= 3 {
                        score += 7.0;
                    }
                }
            }
        } else {
            score += 0.35 * post_residual as f64;
            if post_residual > 20 {
                score += 28.0;
            }
            if post_residual > 40 && next_item_size > post_residual + 30 {
                score += 18.0;
            }
            if post_residual < 10 && next_item_size <= 15 {
                score -= 10.0;
            }
            if post_residual >= bin_capacity / 4 && post_residual <= bin_capacity / 2 {
                score += 12.0;
            }
            let gap = next_item_size - post_residual;
            if gap <= 10 && post_residual > 8 {
                score += 6.0 + 1.2 * gap as f64;
            }
            if gap <= 16 && post_residual > 12 && fitting_bins_count <= 2 {
                score += 10.0 + 0.9 * gap as f64;
            }
            if gap > 0 && gap <= 25 && next_item_size >= bin_capacity / 4 {
                score += 0.25 * (25 - gap) as f64;
            }
            if gap > 0 && gap <= 8 && fitting_bins_count <= 2 {
                score += 8.0 + 2.0 * (8 - gap) as f64;
            }
            if gap > 8 && gap <= 20 && post_residual + next_item_size <= bin_capacity {
                let implied_waste = bin_capacity - post_residual - next_item_size;
                if implied_waste <= 4 {
                    score += 5.0 + 1.5 * (4 - implied_waste) as f64;
                }
            }
            // MUTATION (gen 19): gap-band awareness — when the gap sits in the
            // awkward 11–16 band and the mean residual across open bins is
            // already small (little slack elsewhere), the stranded gap is
            // costlier because no other bin can absorb the next item either.
            if gap >= 11 && gap <= 16 && mean_residual < 0.15 * cap {
                score += 5.0 + 0.8 * (16 - gap) as f64;
            }
        }
    }

    // Deviation from mean residual: reward tight bins nonlinearly
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.55 * dev;
    } else {
        score += 0.4 * dev + 0.06 * dev * dev / cap;
    }

    // Last-chance bin: avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 160.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 260.0 + 110.0 * progress;
        if item_size > bin_capacity / 2 {
            penalty -= 90.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 45.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_capacity / 2 {
            penalty -= 70.0;
        }
        if progress > 0.7 && open_bins_count > 10 {
            penalty += 55.0;
        }
        if item_size <= 10 && progress < 0.3 {
            penalty += 30.0;
        }
        if progress > 0.85 {
            penalty += 40.0;
        }
        if item_size as f64 >= 0.8 * cap {
            penalty += 60.0;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_left = post_residual.saturating_sub(next_item_size);
            if post_residual > next_item_size && worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        if item_size <= 6 && progress > 0.5 {
            penalty -= 25.0;
        }
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        if item_size >= bin_capacity / 2 && progress < 0.2 {
            penalty += 20.0;
        }
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // MUTATION (gen 19): fresh-bin residual tileability — a new bin is
        // more attractive when its post-placement leftover is exactly a
        // multiple of the item size (perfect tiling with future copies),
        // since unknown distributions often repeat size classes.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size).saturating_sub(next_item_size);
            if fresh_left > 0 && item_size >= 4 && fresh_left % item_size == 0 && fresh_left / item_size >= 2 {
                penalty -= 20.0;
            }
        }
        score += penalty;
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }

    if post_residual >= 3 && post_residual <= 8 {
        score -= 6.0;
    }

    // Fine-grained compaction — near-exact fits
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    if post_residual == 2 * item_size {
        score -= 40.0;
    }
    if post_residual == 3 * item_size {
        score -= 18.0;
    }

    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
    }

    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    // Global fragmentation balance
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard — tileable residuals preferred.
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        if pr % (item_size / 2).max(1) == 0 && pr / (item_size / 2).max(1) >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 19): residual-decay compaction — when stream progress is
    // late and open bins are few, residuals in the 3–12 band are prime
    // landing slots for the long tail of small items; reward them more
    // aggressively to squeeze the final bins tighter.
    if progress > 0.6 && open_bins_count <= 8 && post_residual >= 3 && post_residual <= 12 {
        score -= 4.0 + 0.5 * (12 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes (capacity fractions)
    let item_class = (item_size * 4 + bin_capacity - 1) / bin_capacity; // 1..=4
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size * 4 + bin_capacity - 1) / bin_capacity };

    // Reward tight fits: post_residual near zero is ideal
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Items >= 1, so residual 0 is perfect; residual in (0, 10) is dead space under
    // the classic regime, but sizes go down to 1, so weight by class rarity.
    if post_residual > 0 && post_residual < 8 {
        score += 6.0; // tiny unusable sliver
    }

    // Harmonic pairing: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits into post_residual (chained fit), moderate reward
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }
    // Next item cannot use this residual: penalize proportionally
    else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 + 4.0 * (post_residual as f64) / cap;
    }

    // Modulo arithmetic on post_residual: prefer residuals that are "friendly"
    // multiples/divisors of common size classes (10,20,25,50 pattern).
    let friendly = post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual == 0;
    if friendly {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Integer-division thresholds: bucket the residual into harmonic zones.
    let zone = post_residual / 25; // 0..=4
    score += match zone {
        0 => -6.0,          // 0..24: nearly full, great
        1 => -1.0,          // 25..49
        2 => 1.0,           // 50..74
        3 => 3.0,           // 75..99
        _ => 0.0,           // empty/new bin baseline
    };

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a new bin
        } else {
            // Opening a new bin wastes the residual of existing bins; penalize
            // unless all fitting bins would be left with bad residuals.
            score += 8.0 + 0.5 * open_bins_count as f64;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 6.0; // fresh bin serves the lookahead item well
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Spread-awareness: avoid over-fragmenting when many bins are open and mean
    // residual is high (bins are underfilled); prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= 5.0 * fullness * (1.0 - progress);
    score += 2.0 * ((mean_residual - (bin_residual as f64)) / cap).max(-1.0).min(1.0);

    // Late-stream consolidation: as stream ends, favor bins that end exactly full
    if progress > 0.8 && post_residual == 0 {
        score -= 20.0;
    }

    // Small class-coupling bonus: pairing small item into a bin whose class
    // complements it (item_class + zone relationship)
    if item_class >= 3 && zone == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
