    // Perfect / near-perfect fits get dominant rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    } else if post_residual == item_size {
        score -= 120.0;
    }

    // Dead-space avoidance for tiny unusable leftovers
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 20.0 + 0.4 * (dead_threshold - post_residual as f64);
    }

    // Two-step lookahead: chain the next item into this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            score -= (45.0) * (1.0 - two_step_leftover / cap);
            score += 0.5 * two_step_leftover;
            if two_step_leftover >= 1.0 && two_step_leftover <= 12.0 {
                score -= 9.0;
            }
            // Chain depth bonus for large next items
            if next_item_size >= bin_capacity / 3 && two_step_leftover <= 6.0 {
                score -= 14.0;
            }
            // Adaptive tolerance based on scarcity
            let tol = if fitting_bins_count >= 4 { 4.0 } else { 14.0 };
            if two_step_leftover > tol {
                score += 0.8 * (two_step_leftover - tol);
            }
            // Triple-chain: leftover exactly matches the item again
            if two_step_leftover as u32 == item_size {
                score -= 30.0;
            }
            // Residual divisible by item/2 tiles cleanly
            if two_step_leftover > 0.0 {
                let lo = two_step_leftover as u32;
                if item_size >= 6 && lo == item_size / 2 {
                    score -= 12.0;
                } else if lo < item_size / 3 && lo > 0 {
                    score += 5.0;
                }
            }
        } else {
            // Near-miss penalties scaled by gap and scarcity
            let gap = next_item_size - post_residual;
            score += 0.35 * post_residual as f64;
            if post_residual > 20 {
                score += 25.0;
            }
            if gap <= 10 && post_residual > 8 {
                score += 6.0 + 1.2 * gap as f64;
            }
            if gap <= 16 && post_residual > 12 && fitting_bins_count <= 2 {
                score += 10.0 + 0.9 * gap as f64;
            }
            if gap > 0 && gap <= 8 && fitting_bins_count <= 2 {
                score += 8.0 + 2.0 * (8 - gap) as f64;
            }
            // Implied second-level waste when the next item would fit here
            if gap > 8 && gap <= 20 && post_residual + next_item_size <= bin_capacity {
                let implied_waste = bin_capacity - post_residual - next_item_size;
                if implied_waste <= 4 {
                    score += 5.0 + 1.5 * (4 - implied_waste) as f64;
                }
            }
            if post_residual < 10 && next_item_size <= 15 {
                score -= 10.0;
            }
        }
    }

    // Deviation from mean residual: reward tight bins nonlinearly
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.55 * dev;
    } else {
        score += 0.4 * dev + 0.06 * dev * dev / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 160.0;
    }

    // New-bin candidate handling with adaptive penalty
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 260.0 + 110.0 * progress;
        if item_size > bin_capacity / 2 {
            penalty -= 90.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 45.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            penalty -= 70.0;
        }
        if progress > 0.7 && open_bins_count > 10 {
            penalty += 55.0;
        }
        if progress > 0.85 {
            penalty += 40.0;
        }
        if item_size as f64 >= 0.8 * cap {
            penalty += 60.0;
        }
        // Fresh bin attractive when the best fit leaves a large awkward leftover
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size {
            let worst_left = post_residual - next_item_size;
            if worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        // Best-alternative quality gate
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        // Mean-residual-aware gate
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        // Two-item lookahead gate for fresh bins
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // Small items late in the stream are cheap filler for fresh space
        if item_size <= 6 && progress > 0.5 {
            penalty -= 25.0;
        }
        score += penalty;
    } else {
        // Open-bin pressure: consolidate into existing bins
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score -= 2.0 * pressure.min(4.0);
    }

    // Waste ratio term: nonlinear penalty on residual fraction
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }

    // Fine-grained compaction — reward near-exact fits
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    // Self-similar residual chain — residual matches item multiples
    if post_residual == 2 * item_size {
        score -= 40.0;
    }
    if post_residual == 3 * item_size {
        score -= 18.0;
    }

    // Exact two-item packing potential — residual hosts item + next item
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    // Hard dead-space penalty for residuals just below the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 22.0 + 4.0 * (6 - gap) as f64;
        }
    }

    // Protect tight residuals when alternatives are scarce
    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space ratio guard — large residuals are fragmentation risks
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching — prefer residuals in the item's size class
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragment-value guard — small post-residual the next item can't use
    if next_item_size > post_residual && post_residual > 0 {
        let waste_frac = post_residual as f64 / cap;
        if waste_frac < 0.15 {
            score += 8.0 + 40.0 * waste_frac;
        }
        // Awkward 55–75% band refinement
        if waste_frac > 0.55 && waste_frac < 0.75 {
            score += 12.0 + 30.0 * (waste_frac - 0.55);
        }
    }

    // Harmonic-pair bonus — residual hosts item plus item/2
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Global fragmentation balance under high open-bin count
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual <= 10 && post_residual > 0 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        // Multi-use slots are precious under fragmentation
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard — prefer clean multiples of small fillers
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        let half = (item_size / 2).max(1);
        if pr % half == 0 && pr / half >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead space" -> heavy penalty.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        // tiny sliver: unusable for almost anything
        score += 60.0;
    } else if post_residual == 0 {
        // perfect fit: strongly reward
        score -= 120.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // lookahead won't fit here; mild penalty scaled by how close it was
            score += 8.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: prefer existing bins more when many bins are open.
    if bin_residual != bin_capacity {
        score -= 6.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize unless residual pattern is bad everywhere.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.15 * mean_residual;
    }

    // Tight fit reward: how fully the bin is used after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Late in stream: consolidate, avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
