    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // Dead-space ratio refinement in 55–75% band
    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    // Global fragmentation balance
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 10 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // Residual entropy guard — tileable multiples of small fillers.
    if post_residual > 0 && item_size >= 4 {
        let pr = post_residual;
        if pr % (item_size / 2).max(1) == 0 && pr / (item_size / 2).max(1) >= 2 && pr <= item_size * 2 {
            score -= 7.0;
        } else if pr > item_size && pr < item_size * 2 && pr % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 20): mean-residual coupling — when the pool of open bins
    // is much tighter than this candidate's post-residual, the item belongs
    // in a tighter home; conversely a candidate tighter than the pool mean
    // is a premium slot worth extra compaction pressure.
    if open_bins_count > 2 {
        let excess = post_residual as f64 - mean_residual;
        if excess > 8.0 {
            score += 0.35 * (excess - 8.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
