            let chain_waste = (post_residual - next_item_size) as f64;
            score += 0.6 * chain_waste;
            // Small reward if the chain still leaves a placeable amount later.
            if chain_waste >= 10.0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot use this bin's residual; mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average open bin.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (residual_f - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make empty bins unattractive unless nothing sensible fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in the stream, opening bins is fine; early on, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * progress;
        // If next item is huge, a fresh bin is actually useful.
        if next_item_size >= 60 {
            score -= 60.0;
        }
    }

    // Slight preference for filling larger items into tighter bins overall.
    score += 0.1 * (item_size as f64) * (residual_f / bin_capacity as f64);

    score
}

