pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    score -= 1.5 * (1.0 - post / cap) * item;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if the next item can also fit in the leftover space, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 + 10.0 * (nxt / cap);
    }
    // Lookahead penalty: if the next item almost fits but not quite, dead space risk
    if next_item_size > 0 && nxt > post && nxt - post <= 10.0 {
        score += 8.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins are open
    // and when the current bin would leave a usable residual
    if bin_residual == bin_capacity {
        let waste = post / cap;
        score += 25.0 + 2.0 * open_bins_count as f64 + 30.0 * (1.0 - waste);
        // Late in the stream, opening bins is cheaper than fragmenting
        score -= 15.0 * progress;
        // If this is the only option (no open bin fits), soften the penalty
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference for bins below mean residual (balance residuals across bins)
    score += 0.05 * (mean_residual - res).abs();

    // Slight non-linear penalty on large leftovers to discourage unusable slivers
    score += 0.2 * (post * post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits (borrowed strong rewards)
    if post_residual == 0 {
        score -= 800.0;
    } else if post_residual <= 2 {
        score -= 150.0;
    } else if post_residual == item_size {
        score -= 90.0;
    }

    // Two-step lookahead with chain coupling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            score -= (40.0 + 20.0 * (1.0 - two_step_leftover / cap)) ;
            score += 0.5 * two_step_leftover;
            if two_step_leftover <= 2.0 {
                score -= 15.0;
            }
            if two_step_leftover as u32 == item_size {
                score -= 25.0;
            }
            // Adaptive tolerance: scarce fits allow looser chains
            let tol = if fitting_bins_count >= 4 { 4.0 } else { 12.0 };
            if two_step_leftover > tol {
                score += 0.8 * (two_step_leftover - tol);
