            score += 3.0 + 0.1 * ((item_size * 2 - pr) as f64);
        }
    }

    // MUTATION (gen 20): consolidation sweep — late in the stream with many
    // open bins, strongly favor the bin that leaves the smallest residual
    // regardless of chain potential, to flush fragmentation before the tail.
    if progress > 0.6 && open_bins_count > 8 && bin_residual < bin_capacity {
        score -= 0.4 * (bin_residual as f64 - post_residual as f64);
    }

    score
}

