            score -= 4.0 + 0.4 * (20 - post_residual) as f64;
        }
    }

    // MUTATION: next-item scarcity bonus — when only this bin can host the
    // NEXT item, preserving that slot is valuable; reward keeping it intact.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 2.5 * t * (1.0 - t));
    score += poly * cap;

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (5.0 + 40.0 * t);

    // Penalize large dead space relative to mean residual
    score += (pr - mean_residual).max(0.0) * (0.3 + 0.7 * t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving space close to next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild pressure to consolidate into fewer bins early
    score += (open_bins_count as f64) * (1.0 - t) * 0.5;

    // New-bin candidate should only win when post_residual is perfect or open bins are poor
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) + (1.0 - norm_pr) * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong exact/near-exact fit rewards (borrowed from best lineage)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 220.0;
    } else if post_residual == item_size {
        score -= 130.0;
    } else if post_residual == 2 * item_size {
        score -= 40.0;
    }

    // Two-step lookahead chain
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 850.0;
        } else if next_item_size < post_residual {
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            score -= (50.0 + if next_item_size > bin_capacity / 2 { 25.0 } else { 0.0 }) * (1.0 - two_step_leftover / cap);
            score += 0.55 * two_step_leftover;
            if two_step_leftover >= 1.0 && two_step_leftover <= 12.0 {
                score -= 9.0;
            }
            if two_step_leftover as u32 == item_size {
                score -= 30.0;
            }
            let tol = if fitting_bins_count >= 4 { 4.0 } else { 14.0 };
            if two_step_leftover > tol {
                score += 0.8 * (two_step_leftover - tol);
            }
        } else {
            score += 0.35 * post_residual as f64;
            if post_residual > 20 {
                score += 28.0;
            }
            // Near-miss pain: gap just below next item is stranded space
            let gap = next_item_size - post_residual;
            if gap <= 10 && post_residual > 8 {
                score += 6.0 + 1.2 * gap as f64;
            }
            if gap <= 16 && post_residual > 12 && fitting_bins_count <= 2 {
                score += 10.0 + 0.9 * gap as f64;
            }
            if gap <= 6 {
                score += 22.0 + 4.0 * (6 - gap) as f64;
            }
            // Fragment-value guard
            if post_residual > 0 {
                let waste_frac = post_residual as f64 / cap;
                if waste_frac < 0.15 {
                    score += 8.0 + 40.0 * waste_frac;
                }
            }
        }
    }

    // Deviation from mean residual: reward tight bins nonlinearly
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.55 * dev;
    } else {
        score += 0.4 * dev + 0.06 * dev * dev / cap;
    }

    // Last-chance bin: avoid opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 160.0;
    }
    if fitting_bins_count == 2 && post_residual <= 5 {
        score -= 12.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 260.0 + 110.0 * progress;
        if item_size > bin_capacity / 2 {
            penalty -= 90.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 45.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            penalty -= 70.0;
        }
        if progress > 0.7 && open_bins_count > 10 {
            penalty += 55.0;
        }
        if item_size as f64 >= 0.8 * cap {
            penalty += 60.0;
        }
        // Fresh bin attractive when every fitting bin leaves a large awkward leftover
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual > next_item_size {
            let worst_left = post_residual - next_item_size;
            if worst_left > bin_capacity / 3 {
                penalty -= 55.0;
            }
        }
        // Two-item lookahead gate: item+next nearly fills a fresh bin -> cheap open
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 45.0;
            } else if fresh_left > bin_capacity / 2 {
                penalty += 15.0;
            }
        }
        // Best-alternative quality gate
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 35.0;
        }
        if mean_residual > 0.35 * cap {
            penalty += 25.0 * ((mean_residual / cap) - 0.35);
        }
        score += penalty;
    }

    // Mild pressure to keep open bin count low
    score += 2.0 * open_bins_count as f64;

    // Waste ratio term
    let r = post_residual as f64 / cap;
    score += 10.0 * r * r;
    if r > 0.25 && r < 0.5 {
        score += 14.0;
    }
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual <= 2 * next_item_size + 2 {
        score -= 20.0;
    }
    if post_residual >= 3 && post_residual <= 8 {
        score -= 6.0;
    }

    // Fine-grained compaction on tight slack
    let slack = bin_residual as i64 - item_size as i64;
    if slack > 0 && slack <= 4 {
        score -= 18.0 + 3.0 * (4 - slack) as f64;
    }

    if fitting_bins_count > 2 && post_residual > item_size * 2 {
        score += 8.0;
    }

    // Exact two-item packing potential
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 35.0 - 5.0 * pair_slack as f64;
        }
    }

    // Dead-space ratio guard on large residuals
    if post_residual > bin_capacity / 2 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 10.0 + 0.15 * (post_residual as f64 - cap / 2.0);
        } else {
            score -= 8.0;
        }
    }

    // Residual-tier matching
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 10.0;
    } else if post_residual > item_size + 40 {
        score += 6.0;
    }

    // Fragmentation balance: force compaction when spread too thin
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 8.0 * progress {
        if post_residual <= 10 && post_residual > 0 {
            score -= 2.5 * (10 - post_residual) as f64;
        } else if post_residual as f64 > 0.5 * cap {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= next_item_size + item_size {
            score -= 8.0;
        }
    }

    // MUTATION: divisibility tiling bonus — residuals that tile cleanly
    // with the item (or its halves) are harvestable without stranding space.
    if post_residual > 0 && item_size >= 4 {
        let half = (item_size / 2).max(1);
        if post_residual % half == 0 && post_residual / half >= 2 && post_residual <= item_size * 2 {
            score -= 7.0;
        } else if post_residual > item_size && post_residual < item_size * 2 && post_residual % item_size != 0 {
            score += 3.0 + 0.1 * ((item_size * 2 - post_residual) as f64);
        }
    }

    // MUTATION: harmonic-pair bonus — residual hosting item + item/2
    if post_residual == item_size + item_size / 2 && item_size >= 4 {
        score -= 15.0;
    }

    // MUTATION: awkward mid-band penalty — residuals the next item can't
    // use in the 55–75% band are prime fragmentation sources.
    if next_item_size > post_residual {
        if r > 0.55 && r < 0.75 {
            score += 12.0 + 30.0 * (r - 0.55);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small denominators) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Harmonic divisibility bonus: leftover divisible by 5/10/20 packs well.
        let mut harm_bonus = 0.0;
        if pr % 20 == 0 { harm_bonus += 8.0; }
        else if pr % 10 == 0 { harm_bonus += 5.0; }
        else if pr % 5 == 0 { harm_bonus += 3.0; }
        score -= harm_bonus;

        // Dead-space penalty: leftover in awkward bands (1..=9 or 21..=29 etc.)
        // is hard to fill with typical items.
        let q = pr / 10; // integer division threshold class
        let dead = match q {
            0 => 12.0,               // 1..=9 crumbs
            1 => 2.0,                // 10..=19 usable
            2 => 6.0,                // 20..=29 awkward mid
            3 => 0.0,                // 30..=39 good
            4 => 4.0,                // 40..=49
            _ => -6.0,               // large leftover = flexible
        };
        score += dead;

        // Nonlinear coupling: penalty grows with leftover squared fraction.
        let frac = pr as f64 / cap;
        score += 20.0 * frac * frac;
    } else {
        // Perfect fill: huge reward.
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into this bin's post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            // harmonic class of the gap after the lookahead item
            if gap % 10 == 0 { score -= 6.0; }
            score += (gap as f64) * 0.3;
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 4.0;
        }
    } else {
        // Last item: strongly prefer tightest fill.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral baseline, penalize unless current
    // residuals are mostly unusable for this item.
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.5 * open_bins_count as f64;
        // If mean residual is small (bins nearly full), opening fresh is fine.
        score = base - (mean_residual / cap) * 40.0;
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 60 { score -= 10.0; }
    }

    // Mild preference to fill emptier bins when many are open (bin consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 25.0 + 0.5 * (dead_threshold - post_residual as f64);
    }

    // Perfect / near-perfect fits (strengthened from parent)
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual == item_size {
        score -= 20.0;
    }

    // Reward when this bin can also host the next item with its post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // MUTATION: exact chain — residual exactly matches next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // MUTATION: two-step chain quality — leftover after next item matters
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 25.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left as u32 == item_size {
            score -= 18.0;
        } else if two_left > item_size * 2 && two_left > next_item_size {
            score += 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // post residual can't fit next item: near-miss penalty scaled by gap
        let gap = next_item_size - post_residual;
        score += 3.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: adaptive penalty
        let mut penalty = 12.0 * pressure + 10.0 * progress;
        // MUTATION: fresh-bin discount when item+next nearly fills a fresh bin
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 20.0;
            }
        }
        // MUTATION: fresh bin attractive when every fitting bin strands >60% residual
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 15.0;
        }
        // MUTATION: stiffen when many bins already open (fragmentation control)
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        score += penalty;
    } else {
        score -= 2.0 * pressure.min(4.0);
    }

    // Prefer bins whose residual is below mean residual (tighter bins get packed first)
    if bin_residual < bin_capacity {
        let dev = post_residual as f64 - mean_residual;
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // MUTATION: residual-tier matching — prefer residuals in the item's size class
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }

    // MUTATION: multi-slot tiling bonus — residual that exactly hosts repeated items
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // MUTATION: pair-packing potential — residual hosts item + next item tightly
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 15.0 - 3.0 * pair_slack as f64;
        }
    }

    // MUTATION: waste-ratio term for nonlinear residual penalty
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (>= 1 but effectively unusable) are heavily penalized.
    // Items are >= 1, so any residual > 0 can technically hold something,
    // but tiny gaps (< 20) rarely fit realistic items: superlinear penalty.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 20.0 {
            score += 45.0 * (20.0 - pr) / 20.0; // dead-space cliff
        } else if pr < 40.0 {
            score += 10.0 * (40.0 - pr) / 20.0; // moderate waste zone
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, allow opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 8.0 * (0.5 + progress);
    score += pressure;

    // Penalize bins whose residual deviates far below mean residual
    // (i.e., this bin is already tight; leave it for smaller items).
    if (mean_residual - bin_residual as f64) > 15.0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }
    // If next item would NOT fit here but fits the current residual exactly,
    // slight penalty for consuming that opportunity.
    if next_item_size > 0 && next_item_size > post_residual && bin_residual >= next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin is a safe fallback; give it a
    // neutral-but-not-terrible score so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening fresh is fine when stream items are large
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

