                }
            }
            // MUTATION (gen 21): tiling bonus — leftover exactly divisible by
            // the item means the residual can be tiled with more copies of
            // this item without stranding anything.
            if two_step_leftover > 0.0 && item_size >= 2
                && two_step_leftover as u32 % item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 0.35 * post_residual as f64;
            if post_residual > 20 {
                score += 28.0;
            }
            if post_residual > 40 && next_item_size > post_residual + 30 {
