        score += (25.0 + 0.5 * (dead_threshold - post_residual as f64)) * urgency;
    }

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual == item_size {
        score -= 20.0;
    }

    // Reward when this bin can also host the next item with its post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 30.0;
        }
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 25.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left as u32 == item_size {
            score -= 18.0;
        } else if two_left > item_size * 2 && two_left > next_item_size {
            score += 6.0;
        }
        // triple-chain lookahead — residual hosts item, next, and next again
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 14.0;
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size - post_residual;
        score += 3.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        let mut penalty = 12.0 * pressure + 10.0 * progress;
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 20.0;
            }
        }
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        // fresh-bin discount when the item alone nearly fills a fresh bin
        let solo_left = bin_capacity.saturating_sub(item_size);
        if solo_left <= 3 {
            penalty -= 12.0;
        }
        // fresh-bin discount when item + next fills fresh bin almost exactly
        if next_item_size > 0 {
            let pair_left = bin_capacity.saturating_sub(item_size).saturating_sub(next_item_size);
            if pair_left > 4 && pair_left <= 10 {
                penalty -= 6.0;
            }
