        // placing the item in a fresh bin, the stronger the pull toward opening it.
        let fresh_fill = item_size as f64 / cap;
        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        // MUTATION: fresh-bin viability gate — only open a new bin when the
        // resulting leftover pairs well with the observed residual landscape.
        // If the fresh-bin leftover is far from any plausible residual bucket
        // (mean residual), damp the discount so poor openings are avoided.
        let fresh_left = bin_capacity.saturating_sub(item_size);
        let mean_res_u = mean_residual as u32;
