        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // Residual-tier matching
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }

    // Multi-slot tiling bonus
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Pair-packing potential
    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 15.0 - 3.0 * pair_slack as f64;
        }
    }

    // Waste-ratio term for nonlinear residual penalty
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }

    // Endgame tightening — late in the stream, demand tighter fits
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }

    // Fragmentation tax — bins whose post residual is a "stranded" gap
    // (too small for the next item but not near-zero) get a nonlinear penalty
    // that grows mid-stream where consolidation matters most.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strand = (next_item_size - post_residual) as f64 / cap;
        score += (2.0 + 18.0 * progress) * strand * 10.0;
        // extra strand penalty when few fitting alternatives exist,
        // since wasting the only viable bin is costlier then.
        if fitting_bins_count <= 2 {
            score += 5.0 * strand * 10.0;
        }
    }

    // Reward bins whose post residual exactly equals a small future
    // combination (item + next) leaving zero waste on a 2-item chain.
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }

    // Tightness gradient — reward fits whose post residual is small
    // relative to capacity, with a smooth nonlinear (sqrt) shaping that
    // favors near-full bins without over-rewarding trivially small items.
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
    }

    // MUTATION: two-step compaction lookahead — when this bin's post residual
    // cannot host the next item, but the item AFTER a fresh placement could
    // absorb a smaller future gap, reward bins whose stranded residual is
    // still reusable by mid-sized items (residual >= half of next item).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual * 2 >= next_item_size {
        score -= 4.0 + 6.0 * (1.0 - progress);
    }

    // MUTATION: mean-anchored dead-space shaping — penalize post residuals that
    // sit in the "unusable band" just above the mean residual, where they are
    // unlikely to match future item sizes drawn from the observed distribution.
    if post_residual > 0 && mean_residual > 0.0 {
        let band = post_residual as f64 - mean_residual;
        if band > 0.0 && band < 8.0 {
            score += 1.5 * (8.0 - band) * (1.0 - progress * 0.5);
        }
    }

    score
}

