        if solo_left <= 3 {
            penalty -= 12.0;
        }
        // fresh-bin discount when item + next fills fresh bin almost exactly
        if next_item_size > 0 {
            let pair_left = bin_capacity.saturating_sub(item_size).saturating_sub(next_item_size);
            if pair_left > 4 && pair_left <= 10 {
