    // Fragmentation tax — bins whose post residual is a "stranded" gap
    // (too small for the next item but not near-zero) get a nonlinear penalty
    // that grows mid-stream where consolidation matters most.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
