        score += 3.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        let mut penalty = 12.0 * pressure + 10.0 * progress;
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
            let fresh_left = bin_capacity - item_size - next_item_size;
            if fresh_left <= 4 {
                penalty -= 20.0;
            }
        }
        if fitting_bins_count >= 1 && post_residual as f64 > 0.6 * cap {
            penalty -= 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        let solo_left = bin_capacity.saturating_sub(item_size);
        if solo_left <= 3 {
            penalty -= 12.0;
        }
        if next_item_size > 0 {
            let pair_left = bin_capacity.saturating_sub(item_size).saturating_sub(next_item_size);
            if pair_left > 4 && pair_left <= 10 {
                penalty -= 6.0;
            }
        }
        let fresh_fill = item_size as f64 / cap;
        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            if progress < 0.55 {
                penalty -= mid_bonus;
            } else {
                penalty -= 0.35 * mid_bonus;
            }
        }
        let solo_left_big = bin_capacity.saturating_sub(item_size);
        if solo_left_big > item_size && solo_left_big > next_item_size && solo_left_big as f64 > cap * 0.5 {
            penalty += 4.0 + 6.0 * progress;
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
            }
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        // MUTATION (gen 27): fresh-bin fragment forecast — opening a bin whose
        // leftover after placing the item is small but unfillable by the next
        // item creates a new dead tile; penalize, but relax late when closing
        // bins matters less than consolidating big items.
        if next_item_size > 0 {
            let fresh_left = bin_capacity.saturating_sub(item_size);
            if fresh_left > 0 && fresh_left < next_item_size && fresh_left <= 12 {
                penalty += (5.0 + 4.0 * progress) * (1.0 - fresh_left as f64 / 12.0);
            }
        }
        score += penalty;
    } else {
        score -= 2.0 * pressure.min(4.0);
    }

    if bin_residual < bin_capacity {
        let dev = post_residual as f64 - mean_residual;
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    if next_item_size > 0 && post_residual >= item_size + next_item_size {
        let pair_slack = post_residual - (item_size + next_item_size);
        if pair_slack <= 3 {
            score -= 15.0 - 3.0 * pair_slack as f64;
        }
    }

    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }

    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let strand = (next_item_size - post_residual) as f64 / cap;
        score += (2.0 + 18.0 * progress) * strand * 10.0;
        if fitting_bins_count <= 2 {
