        score -= 10.0;
    }

    // Global waste guard — penalize bins whose post-residual strands the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    // MUTATION (gen 29): near-miss dead-space amplifier — the most damaging
    // dead space is a post-residual that sits just below the next item's size
    // (a "near miss" that would have closed the bin). Escalate the penalty
    // quadratically as the gap shrinks toward zero, and weight it by how much
    // of the bin was consumed, so we avoid burning large bins on near-misses.
    if next_item_size >= 2 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8 {
            let near_miss = (1.0 - gap / 8.0).powi(2);
            let consumed = (item_size as f64 / bin_residual.max(1) as f64).clamp(0.0, 1.0);
            score += (6.0 + 14.0 * near_miss) * (0.4 + 0.6 * consumed) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION (gen 29): exact-complement closure — when the bin's residual
    // equals item + next item exactly, this bin is guaranteed to close in two
    // steps with zero dead space; deepen the reward as open bins accumulate,
    // since closing bins early directly reduces the open-bin footprint.
    if next_item_size > 0 && bin_residual == item_size + next_item_size {
        score -= 8.0 + 0.4 * (open_bins_count as f64).min(15.0);
    }

    // MUTATION (gen 29): sliver-guard on tiny post-residuals relative to the
    // next item — residuals in (0, next/4) are almost never recoverable by
    // future items; penalize proportionally to how unrecoverable they are,
    // unless the residual is small enough to be closed by any small item.
    if next_item_size >= 4 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 * 0.25 {
        let unusable = 1.0 - (post_residual as f64) / (next_item_size as f64 * 0.25);
        score += 5.0 * unusable * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
