        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Exact-residual harmonics — guaranteed multi-step closure; escalate the
    // reward as the stream progresses.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-band competition — reward the "hot band" just below the next
    // item's size threshold complement.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    // MUTATION (gen 29): near-miss gap shaping — when the next item barely
    // misses this bin's post-residual (gap <= 8), the stranded space is
    // recoverable if a later small item arrives; reward bins whose gap is
    // small proportionally, penalize proportionally larger gaps, weighted by
    // stream progress since late-stage near-misses are the dominant waste
    // source.
    if post_residual > 0 && next_item_size > 2 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 8.0 {
            // Tiny gap: keep the bin alive — a small item may still close it.
            score -= 2.5 * (1.0 - gap / 8.0) * (0.5 + 0.5 * progress);
        } else {
            // Large gap: this bin's residual is likely permanent waste.
            score += 1.5 * (gap - 8.0).min(15.0) * (0.4 + 0.6 * progress);
        }
    }

    score
}

