            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: when open bins would strand more than half
        // of the next item's size, a fresh bin is cheaper.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
