        // leftover after this item cannot tile the next item cleanly, soften
        // the opening bias; when it can, deepen the discount.
        if next_item_size > 0 && fresh_two_check(bin_capacity, item_size) >= next_item_size {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            let tiles = fresh_two / next_item_size;
            let rem = fresh_two % next_item_size;
            if tiles >= 2 && rem <= 3 {
                penalty -= 7.0 + 2.0 * (3 - rem) as f64;
            } else if rem > 0 && rem < next_item_size && tiles == 1 {
