    // of capacity left dead after placement, with refund for closable gaps.
    // MUTATION (gen 30): governor weight now scales with open-bin congestion
    // and mean-residual tightness, so dead space is punished hardest exactly
    // when fragmentation is the bottleneck; refund band widened slightly.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        let congestion = ((open_bins_count as f64) / 12.0).min(1.0);
        let tight_stream = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
