            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 5 {
                score -= 3.0 + 0.5 * (5 - two_left) as f64;
            }
        }
    }

    // Scarcity-aware deep-fill bonus (retained from gen 29).
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // MUTATION (gen 30): near-exact closure sweep — reward placements whose
    // post-residual sits within a narrow band of the next item, scaled by
    // how close the gap is, to squeeze out the last few wasted bins.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = post_residual - next_item_size;
        if over <= 6 {
            score -= (7.0 - over as f64) * (0.6 + 0.4 * progress);
        }
    }

    score
}

