        }
        // MUTATION (gen 30): mean-residual-driven fresh-bin relief — when the
        // average open-bin residual is already too small to host the next
        // item, a fresh bin preserves clean space instead of fragmenting.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            let deficit = (next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64;
            penalty -= 8.0 * deficit * (0.5 + 0.5 * (1.0 - progress));
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
