        // MUTATION (gen 31): residual-variance governor — when open-bin
        // residuals are spread widely, a fresh bin with a predictable
        // remainder (capacity - item) is preferable to a scattered fit.
        // Strength scales with observed spread and stream progress.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
