            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — when placing the item in a fresh bin
        // leaves exactly the next item's size, the bin closes perfectly in
        // two steps. Escalate the reward when existing open bins cannot offer
        // such a guaranteed closure (mean residual does not match the next
        // item), making the fresh option decisive.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 14.0 * mismatch.min(0.5) * 2.0;
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless. A fresh bin placed
        // with a large item there is almost free, so relax the fresh-bin
        // penalty proportionally to how much usable residual capacity
        // actually remains across open bins.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // MUTATION (gen 33): dead-space efficiency gate — compare the dead
        // space a fresh bin would strand (capacity - item - next item, if
        // the next item follows) against the mean dead space open bins
        // would leave. Open a fresh bin only when it genuinely strands less.
        if next_item_size > 0 {
            let fresh_two = cap - item_size as f64;
            if fresh_two >= next_item_size as f64 {
                let fresh_dead = fresh_two - next_item_size as f64;
                let open_dead = (mr - next_item_size as f64).max(0.0);
                let delta = fresh_dead - open_dead;
                // Fresh bin strands more: penalize proportionally.
                if delta > 0.0 {
                    penalty += 14.0 * (delta / cap) * (1.2 - 0.5 * progress);
                } else {
                    // Fresh bin strands less (or closes perfectly): reward.
                    penalty -= 14.0 * ((-delta) / cap) * (1.2 - 0.5 * progress);
                }
                // Hard gate: if the fresh remainder dead space exceeds the
                // mean open-bin dead space by a wide margin, refuse fresh.
                if fresh_dead > open_dead + 0.12 * cap && fitting_bins_count >= 1 {
                    penalty += 20.0 * (1.0 - progress);
                }
            } else {
                // Fresh bin cannot even host the next item after this one:
                // it would strand the whole remainder. Strong refusal unless
                // the item nearly fills the bin on its own.
                let stranded = fresh_two;
                if stranded > 0.2 * cap && fresh_fill < 0.8 {
                    penalty += 10.0 * (stranded / cap) * (1.0 - 0.4 * progress);
                }
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard — penalize bins whose post-residual strands the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward,
    // escalated late in the stream to eliminate dead space.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    // Dead-space-ratio governor — continuous quadratic term on the fraction
    // of capacity left dead after placement, with refund for closable gaps.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        // Dead-space refund escalation — when the dead space exactly tiles
        // with the next item, refund more of the quadratic penalty.
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
        // MUTATION (gen 33): dead-space opportunity cost — penalize dead
        // space that exceeds the mean residual by a margin, since a better
        // placement elsewhere would have left less stranded capacity. The
        // penalty grows with how far above the mean the dead space sits.
        if next_item_size > 0 {
            let excess = dead - mean_residual.max(0.0);
            if excess > 2.0 {
                score += 3.5 * (excess / cap) * (1.0 - 0.3 * progress);
            }
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Mid-residual compaction pull — placements leaving a mid-band residual
    // (10–25% of capacity) are mild targets for small future items.
    if post_residual >= 10 && post_residual as f64 <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (0.25 * cap));
    }

    // Near-perfect-fill coupling — when the item nearly exhausts the bin's
    // residual (>= 80% consumed), grant an escalating bonus that grows with
    // stream progress.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed >= 0.80 {
            let depth = (consumed - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 33): residual-floor competition — among fitting bins,
    // prefer the one whose post-residual lands closest to (but not below)
    // the next item's size, so that the next placement closes the bin
    // exactly. Continuous version of the two-step closure bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let overshoot = (post_residual - next_item_size) as f64;
        if overshoot <= 0.3 * cap {
            score -= 10.0 * (1.0 - overshoot / (0.3 * cap)) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: when open bins would strand more than half
        // of the next item's size, a fresh bin is cheaper.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Residual-variance governor — when open-bin residuals are spread
        // widely, a fresh bin with a predictable remainder is preferable.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — when placing the item in a fresh bin
        // leaves exactly the next item's size, the bin closes perfectly in
        // two steps. Escalate the reward when existing open bins cannot offer
        // such a guaranteed closure (mean residual does not match next item).
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 14.0 * mismatch.min(0.5) * 2.0;
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless. A fresh bin placed
        // with a large item there is almost free, so relax the fresh-bin
        // penalty proportionally to how much usable residual capacity
        // actually remains across open bins.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // MUTATION (gen 33): fresh-bin remainder-pair coupling — when the
        // fresh remainder can host the next item AND the leftover after
        // that is either zero or smaller than any plausible item (<= 2),
        // the fresh bin is a guaranteed 2-step closure; deepen the reward
        // as the stream progresses since late closures save whole bins.
        if next_item_size >= 2 && bin_capacity > item_size {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem > next_item_size {
                let tail = fresh_rem - next_item_size;
                if tail <= 2 {
                    penalty -= 16.0 * (0.4 + 0.6 * progress);
                }
            }
        }
        // MUTATION (gen 33): dead-space budget coupling for fresh bins —
        // penalize opening a bin whose post-placement remainder is dead
        // space (smaller than next item) unless the item is large enough
        // that the fill fraction justifies it. This suppresses the main
        // source of wasted bins: fresh bins opened for small items that
        // strand most of their capacity.
        if next_item_size > 0 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem > 0 && fresh_rem < next_item_size {
                let fill_frac = item_size as f64 / cap;
                let dead_frac = fresh_rem as f64 / cap;
                if fill_frac < 0.6 {
                    penalty += 20.0 * dead_frac * (1.2 - fill_frac);
                } else {
                    penalty -= 4.0 * fill_frac;
                }
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard — penalize bins whose post-residual strands the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward,
    // escalated late in the stream to eliminate dead space.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    // Dead-space-ratio governor — continuous quadratic term on the fraction
    // of capacity left dead after placement, with refund for closable gaps.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        // Dead-space refund escalation — when the dead space exactly tiles
        // with the next item, refund more of the quadratic penalty.
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Mid-residual compaction pull — placements leaving a mid-band residual
    // (10–25% of capacity) are mild targets for small future items.
    if post_residual >= 10 && post_residual as f64 <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (0.25 * cap));
    }

    // Near-perfect-fill coupling — when the item nearly exhausts the bin's
    // residual (>= 85% consumed), grant an escalating bonus that grows with
    // stream progress. Slightly widened to 80% to catch more near-closures
    // without distorting mid-band placements.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consumed = item_size as f64 / bin_residual as f64;
        if consumed >= 0.80 {
            let depth = (consumed - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 33): residual-dead-space triage — among bins that can
    // host the next item after this placement, prefer the one whose
    // remaining dead space after the NEXT placement is smallest. Approximate
    // this by rewarding post-residuals in the tight band [next, next+2]
    // proportionally harder when many bins compete, steering selection
    // toward minimal-dead-space candidates and directly attacking the
    // diagnosed dead-space weakness.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 2 {
        let tail = post_residual - next_item_size;
        if tail <= 2 {
            score -= (6.0 + 3.0 * (2 - tail) as f64)
                * (1.0 + 0.5 * (fitting_bins_count.min(6) as f64 - 2.0) / 4.0)
                * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 33): open-bin dead-space tax — for existing bins whose
    // placement leaves a remainder smaller than the next item (pure dead
    // space), tax the waste proportionally to the dead fraction, scaled by
    // how many alternative bins exist. With few alternatives the tax fades
    // so we never strand the item entirely.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && bin_residual < bin_capacity {
        let dead_frac = post_residual as f64 / cap;
        let alt_scale = ((fitting_bins_count as f64 - 1.0) / 3.0).clamp(0.0, 1.0);
        score += 10.0 * dead_frac * alt_scale * (0.6 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
