    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold, since such slivers remain usable
    // by small items while larger ones are excluded.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    // Mid-residual compaction pull — placements leaving a mid-band
    // residual (10–25% of capacity) are mild targets for small future
    // items, worth a small reward early-to-mid stream.
    if post_residual >= 10 && post_residual as f64 <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (0.25 * cap));
    }

    // MUTATION (gen 32→33): dead-space fragmentation governor — penalize
    // placements that strand a dead core which is BOTH too small for the
    // next item and not a sliver (the worst zone: unusable now, unlikely
    // to close later). Scale the penalty by how many competing bins
    // exist, so under scarcity we still accept the imperfect fit.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 3 {
        let stranded_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        let zone = ((post_residual as f64 / cap) - 0.05).max(0.0) / 0.20;
        let competition = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 6.0 * stranded_frac * zone.min(1.0) * competition * (0.6 + 0.4 * (1.0 - progress));
    }

    // MUTATION (gen 32→33): dual-closure lookahead — reward placements
    // where the post-residual can host the next item AND the remaining
    // part after that still fits a plausible small item (residual after
    // two steps lies in the 1–6 sliver band, i.e. near-certain closure).
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let after_two = post_residual - 2 * next_item_size;
        if after_two <= 6 {
            score -= (10.0 + 2.0 * (6 - after_two) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 32→33): residual-efficiency sharpening — replace the
    // flat mean-residual comparison with a graded term that rewards bins
    // whose post-residual sits closest to the next item's size, steering
    // selection toward exact-fit candidates instead of merely "tight" ones.
    if next_item_size > 0 && post_residual > 0 {
        let align = ((post_residual as f64 - next_item_size as f64) / next_item_size.max(1) as f64).min(1.0);
        score += 5.0 * align * (1.0 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fills strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened for tiny slivers.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Dead-space-ratio governor with tiling refund.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            }
        }
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
        // Waste-fraction term scaled by progress.
        let waste_frac = gap as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
    }

    // Exact-residual harmonics — multi-step closure reward.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
