        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && post_residual as f64 <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (0.25 * cap));
    }

    // MUTATION (gen 34): dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = post_residual as f64;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // MUTATION (gen 34): dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // MUTATION (gen 35): dead-space reclamation forecasting — among bins
    // that cannot host the next item, prefer those whose stranded dead
    // space is small relative to the *whole pool* of open-bin capacity.
    // A stranded remainder that is a small fraction of the aggregate
    // open slack is likely to be reclaimed by future small items, so it
    // earns a scaled refund; large stranded chunks relative to the pool
    // are penalized progressively. This sharpens the diagnosed dead-space
    // weakness by ranking stranded bins by aggregate reclaimability
    // rather than only by local closeness to the mean residual.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pool_total = (mean_residual.max(0.0) * open_bins_count.max(1) as f64).max(1.0);
        let reclaim = 1.0 - (dead / pool_total).clamp(0.0, 1.0);
        score -= 6.0 * reclaim * reclaim * (0.35 + 0.65 * progress);
        score += 3.0 * (1.0 - reclaim) * (0.5 + 0.5 * (1.0 - progress));
        // Extra relief when the stranded remainder could combine with the
        // mean pool slack to host the next item (cross-bin pairing view).
        if dead + mean_residual >= next_item_size as f64 && fitting_bins_count <= 3 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 35): dead-space tiering refinement — steepen the
    // escalation knee from 30% to 27% dead space late in the stream, and
    // slightly widen the low-ratio refund band to 18%, so usable slivers
    // stay attractive while locking-in capacity is punished earlier.
    if post_residual > 0 {
        let dr = dead / cap;
        let knee = if progress > 0.5 { 0.27 } else { 0.30 };
        if dr > knee {
            score += 14.0 * (dr - knee) / (1.0 - knee) * (0.5 + 0.5 * progress);
        } else if dr < 0.18 {
            score -= 3.0 * (0.18 - dr) / 0.18 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless; relax the
        // fresh-bin penalty proportional to usable residual capacity.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor — continuous quadratic term on the
    // dead-space fraction, with a refund when the dead space exactly
    // tiles with the next item.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills, penalize shallow
    // placements that leave a non-tileable dead core.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — when the item consumes >= 80% of
        // the bin's residual, grant an escalating bonus that grows with
        // stream progress, targeting near-closures.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && post_residual as f64 <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (0.25 * cap));
    }

    // Dead-space salvage ranking — among bins that strand space below the
    // next item's size, prefer the one whose stranded remainder is closest
    // to being consumed by the aggregate leftover pool.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = post_residual as f64;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering — steeper escalation above 30% dead space,
    // stability refund below 15%.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // MUTATION (gen 35): scarcity-weighted dead-space escalation —
    // the dead-space ratio penalty now couples with fitting-bin scarcity:
    // when many bins can host the item, a high dead-space ratio in any
    // single bin is less costly, but when only a couple of bins fit, a
    // wasteful placement locks away nearly all remaining flexibility.
    // This sharpens the diagnosed dead-space weakness in exactly the
    // regimes where it matters most.
    if post_residual > 0 && next_item_size > 0 {
        let dr = dead / cap;
        let scarcity = (1.0 - (fitting_bins_count.min(6) as f64 / 6.0)).clamp(0.0, 1.0);
        if dr > 0.25 && fitting_bins_count <= 3 {
            score += 10.0 * (dr - 0.25) * scarcity * (0.4 + 0.6 * progress);
        }
        // Complementary refund: a low dead-space ratio under scarcity is
        // the most valuable compaction act in the stream.
        if dr < 0.10 && fitting_bins_count <= 2 {
            score -= 5.0 * (0.10 - dr) / 0.10 * scarcity * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 35): residual-pool alignment for medium dead space —
    // when the post-residual sits in the awkward band just below the next
    // item's size, reward bins whose stranded amount equals a small
    // multiple of the mean open residual, since the aggregate pool of
    // leftovers is the likeliest filler for such gaps.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && fitting_bins_count >= 2 {
        let stranded = post_residual as f64;
        let pool = mean_residual.max(1.0);
        let ratio = stranded / pool;
        if (ratio - ratio.round()).abs() < 0.15 && ratio >= 0.5 && ratio <= 3.0 {
            score -= 4.0 * (1.0 - progress) * (stranded / cap * 50.0).min(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless; relax the
        // fresh-bin penalty proportional to usable residual capacity.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor — continuous quadratic term on the
    // dead-space fraction, with a refund when the dead space exactly
    // tiles with the next item.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills, penalize shallow
    // placements that leave a non-tileable dead core.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — when the item consumes >= 80% of
        // the bin's residual, grant an escalating bonus that grows with
        // stream progress, targeting near-closures.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && post_residual as f64 <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (0.25 * cap));
    }

    // MUTATION (gen 34): dead-space salvage ranking — among bins that
    // strand space below the next item's size, prefer the one whose
    // stranded remainder is closest to being consumed by small items.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = post_residual as f64;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // MUTATION (gen 34): dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // MUTATION (gen 35): residual-homogeneity compaction — when several
    // bins can fit the item, steer toward the bin whose post-residual
    // lands closest to the aggregate mean residual, so remaining open
    // bins converge into a uniform band that future items can tile
    // efficiently. Deviation is scaled by scarcity: with few fitting
    // bins the pull tightens, since misfit residuals there are the
    // primary source of dead space late in the stream.
    if post_residual > 0 && fitting_bins_count >= 1 && bin_residual < bin_capacity {
        let target = mean_residual.max(1.0);
        let homog = ((post_residual as f64 - target) / cap).abs().clamp(0.0, 1.0);
        let scarcity = 1.0 + 2.0 / (fitting_bins_count as f64);
        let pull = 5.0 * homog * scarcity * (0.35 + 0.65 * progress);
        score += pull;
        // Refund when the post-residual still tiles with the next item,
        // so homogenization never overrides guaranteed closures.
        if next_item_size >= 2 && post_residual % next_item_size == 0 {
            score -= 0.6 * pull;
        }
        // Complementary tightening: bins whose post-residual sits within
        // a narrow window around the mean earn a stability discount,
        // reinforcing the uniform-band attractor without flattening
        // exact-fit bonuses.
        if homog < 0.05 {
            score -= 2.0 * (1.0 - homog / 0.05) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 35): late-stream residual draining — past 70% of the
    // stream, prefer draining bins with the largest residuals when their
    // post-residual becomes unusable for typical items, converting
    // stranded capacity into closed bins rather than leaving many
    // half-empty bins open.
    if progress > 0.7 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let drain = (post_residual as f64 / cap) * (progress - 0.7) / 0.3;
        score -= 6.0 * drain * (open_bins_count as f64).min(12.0) / 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        // MUTATION (gen 35): fresh-bin tiling sharpening — when the fresh
        // remainder after this item equals the next item's size plus a
        // small sliver, the sliver is near-certain waste; penalize the
        // fresh bin proportionally to the sliver so near-closures win.
        if next_item_size >= 2 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem > next_item_size && fresh_rem - next_item_size <= 4 {
                penalty += 3.0 + 1.5 * (fresh_rem - next_item_size) as f64;
            }
        }
        score += penalty;
    }

    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if (post_residual as f64) < hot_lo {
            score -= 4.0 * (1.0 - (post_residual as f64) / hot_lo);
        }
    }

    if post_residual >= 10 && post_residual as f64 <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (0.25 * cap));
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = post_residual as f64;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // MUTATION (gen 35): residual-pool salvage refinement — when the
    // stranded remainder matches the aggregate open-residual pool within
    // a tight band, amplify the refund late in the stream (small items
    // from the pool can close it); when the pool is far above the
    // stranded space, the pool will drain into other bins and this
    // stranded space becomes orphaned, so escalate the penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && fitting_bins_count >= 2 {
        let stranded = post_residual as f64;
        let pool = mean_residual.max(1.0);
        let diff = (stranded - pool).abs();
        if diff <= 2.0 {
            score -= (3.0 + 2.0 * (2.0 - diff)) * (0.5 + 0.5 * progress);
        } else if pool > stranded + 6.0 {
            score += 2.0 * ((pool - stranded) / cap).min(0.3) * 10.0 * (1.0 - 0.4 * progress);
        }
    }

    // MUTATION (gen 35): near-closure depth sharpening — among bins whose
    // post-residual is just above the next item's size (off by a few
    // units), the dead sliver is nearly unrecoverable; penalize it
    // progressively so exact-fit bins dominate the ranking.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        let sliver = (post_residual - next_item_size) as f64;
        score += (2.0 + 2.0 * (3.0 - sliver)) * (0.4 + 0.6 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless; relax the
        // fresh-bin penalty proportional to usable residual capacity.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
