    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let sliver = (dead / (next_item_size as f64)).clamp(0.0, 1.0);
        score -= 5.0 * (1.0 - sliver) * (1.0 - sliver) * (0.3 + 0.7 * (1.0 - progress));
        // If the sliver is small enough that a typical small item
        // (<= 1/3 of the next item) could fill it, grant a mild refund.
        if dead >= 1.0 && dead <= (next_item_size as f64) / 3.0 {
            score -= 2.0 * (1.0 - dead / ((next_item_size as f64) / 3.0));
        }
    }

    // MUTATION (gen 39): fleet-residual conservation gate — when the
    // aggregate open residual is barely enough to host the next item,
    // any placement that strands a residual just above zero is precious;
    // reward keeping at least one bin in the tileable band and penalize
    // placements that push the fleet's total usable residual below the
    // next item's size.
    if next_item_size > 0 && post_residual > 0 && open_bins_count >= 2 {
        let fleet = mean_residual * (open_bins_count as f64);
        let fleet_after = fleet - dead;
        if fleet_after < next_item_size as f64 && fleet >= next_item_size as f64 {
            let loss_frac = (1.0 - fleet_after / next_item_size as f64).clamp(0.0, 1.0);
            score += 6.0 * loss_frac * (0.5 + 0.5 * progress);
        } else if fleet_after >= next_item_size as f64 && dead <= 6.0 {
