        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless; relax the
        // fresh-bin penalty proportional to usable residual capacity.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor — continuous quadratic term on the
    // dead-space fraction, with a refund when the dead space exactly
    // tiles with the next item.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills, penalize shallow
    // placements that leave a non-tileable dead core.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — when the item consumes >= 80% of
        // the bin's residual, grant an escalating bonus that grows with
        // stream progress, targeting near-closures.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // MUTATION (gen 34): dead-space salvage ranking — among bins that
    // strand space below the next item's size, prefer the one whose
    // stranded remainder is closest to being consumed by small items.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // MUTATION (gen 34): dead-space ratio tiering — steeper escalation
    // above 30% dead space, small stability refund below 15%.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // MUTATION (gen 36): dead-space pool alignment — a placement whose
    // post-residual matches the aggregate open-residual pool closely
    // keeps future small items usable across bins; reward that alignment,
    // penalize residuals that drift away from the pool and thus strand
    // capacity no later item will likely consume. Scaled by open-bin
    // count since alignment only matters when alternatives exist.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        // Refund when the residual is a near-exact complement of the
        // next item, keeping the pool-aligned bin on the closure path.
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 36): residual-band sharpening — among bins whose
    // post-residual cannot host the next item but is within a narrow
    // miss window, prefer the bin with the largest residual (closest
    // to hosting), since it minimizes wasted capacity in the miss band.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 37): variance-collapse targeting — among placements
    // that leave a usable post-residual, prefer the one whose resulting
    // residual sits closest to the current mean residual, shrinking the
    // residual variance sigma_res so future items tile the fleet of
    // open bins uniformly. Weighted by scarcity of fitting options.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 37): residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 37): dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 38): variance-collapse refinement — when the pool
    // itself is a sliver (mean residual far below the next item's size),
    // the fleet is drifting toward dead space; counteract by rewarding
    // placements whose post-residual RECOVERS toward the next item's
    // size, steering the mean residual back into a tileable band instead
    // of letting it collapse onto unusable slivers.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // MUTATION (gen 38): residual-quantile competition — when several
    // bins can host the item, prefer the placement that leaves the
    // post-residual closest to the *smallest* viable residual band
    // (just under next_item_size) rather than the mean: small residual
    // variance alone can lock the fleet at a wasteful level, so add a
    // mild pull toward compact residuals when many bins remain open.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): dead-space slope sharpening — the diagnosed
    // weakness is residual/dead-space ratio. Escalate the quadratic
    // dead-space governor into a cubic tail so large stranded cores
    // (dr > 0.4) are punished disproportionately, while granting a
    // small refund when the dead space is an exact multiple of the
    // next item's size (tileable waste is recoverable waste).
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.4 {
            score += 10.0 * (dr - 0.4) * (dr - 0.4) / 0.36 * (0.4 + 0.6 * progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.5 * dr * (0.5 + 0.5 * progress);
            } else {
                // Fractional-tile proximity: residuals that nearly tile
                // (remainder small relative to tile size) are one small
                // item away from closure — nudge them upward in rank.
                let prox = rem as f64 / next_item_size as f64;
                if prox < 0.35 {
                    score -= 2.0 * (0.35 - prox) / 0.35 * (0.3 + 0.7 * progress);
                }
            }
        }
    }

    // MUTATION (gen 40): scarcity-weighted residual compaction — when
    // few bins can host the item, the choice of bin determines whether
    // the fleet retains a usable residual. Strengthen the compaction
    // pull toward the smallest viable post-residual in exactly those
    // scarce moments, and relax it when alternatives abound.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(4.0) / 4.0;
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 {
            let compact = 1.0 - (over / (cap * 0.5)).clamp(0.0, 1.0);
            score -= 3.0 * compact * compact * scarcity * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): endgame sliver sweep — in the final stretch,
    // any residual that cannot host the next item is almost certainly
    // permanent waste. Penalize it steeply, but refund when the residual
    // is small enough that a later tiny item (<= 8) could still close it.
    if progress > 0.75 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unrecoverable = post_residual > 8;
        if unrecoverable {
            score += 5.0 * (1.0 - progress) * (post_residual as f64 / next_item_size.max(1) as f64).min(1.0);
        } else {
            score -= 3.0 * (1.0 - post_residual as f64 / 8.0) * (progress - 0.75) / 0.25;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless; relax the
        // fresh-bin penalty proportional to usable residual capacity.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor — continuous quadratic term on the
    // dead-space fraction, with a refund when the dead space exactly
    // tiles with the next item.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills, penalize shallow
    // placements that leave a non-tileable dead core.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — when the item consumes >= 80% of
        // the bin's residual, grant an escalating bonus that grows with
        // stream progress, targeting near-closures.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // MUTATION (gen 34): dead-space salvage ranking — among bins that
    // strand space below the next item's size, prefer the one whose
    // stranded remainder is closest to being consumed by small items.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // MUTATION (gen 34): dead-space ratio tiering — steeper escalation
    // above 30% dead space, small stability refund below 15%.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // MUTATION (gen 36): dead-space pool alignment — a placement whose
    // post-residual matches the aggregate open-residual pool closely
    // keeps future small items usable across bins; reward that alignment,
    // penalize residuals that drift away from the pool and thus strand
    // capacity no later item will likely consume. Scaled by open-bin
    // count since alignment only matters when alternatives exist.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        // Refund when the residual is a near-exact complement of the
        // next item, keeping the pool-aligned bin on the closure path.
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 36): residual-band sharpening — among bins whose
    // post-residual cannot host the next item but is within a narrow
    // miss window, prefer the bin with the largest residual (closest
    // to hosting), since it minimizes wasted capacity in the miss band.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 37): variance-collapse targeting — among placements
    // that leave a usable post-residual, prefer the one whose resulting
    // residual sits closest to the current mean residual, shrinking the
    // residual variance sigma_res so future items tile the fleet of
    // open bins uniformly. Weighted by scarcity of fitting options.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 37): residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 37): dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 38): variance-collapse refinement — when the pool
    // itself is a sliver (mean residual far below the next item's size),
    // the fleet is drifting toward dead space; counteract by rewarding
    // placements whose post-residual RECOVERS toward the next item's
    // size, steering the mean residual back into a tileable band instead
    // of letting it collapse onto unusable slivers.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // MUTATION (gen 38): residual-quantile competition — when several
    // bins can host the item, prefer the placement that leaves the
    // post-residual closest to the *smallest* viable residual band
    // (just under next_item_size) rather than the mean: small residual
    // variance alone can lock the fleet at a wasteful level, so add a
    // mild pull toward compact residuals when many bins remain open.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): dead-space saturation ramp — the diagnosed
    // weakness is residual/dead-space waste. Add a steeper cubic
    // escalation on the dead-space fraction once it exceeds the
    // tileability horizon (half the next item's size), so placements
    // that strand genuinely unusable capacity are pushed down hard,
    // while dead space that the next item can still consume is exempt.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        // Complementary salvage credit: dead space within the horizon is
        // cheap and may be consumed by small items — refund proportionally.
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): fleet-dead-space drain — track how much dead
    // space the fleet as a whole is accumulating (mean residual far
    // below the next item's size means most open bins are stranded).
    // When that happens, strongly prefer the placement that CLOSES a
    // bin outright (post_residual == 0) or leaves the smallest residual,
    // actively draining stranded capacity instead of spreading it.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 40): scarcity-tiered depth bonus — when only one or
    // two bins can host the item, deepen the reward for placements that
    // leave a residual exactly tileable by the next item, so scarce
    // capacity is spent on guaranteed closures rather than loose fits.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless; relax the
        // fresh-bin penalty proportional to usable residual capacity.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor — continuous quadratic term on the
    // dead-space fraction, with a refund when the dead space exactly
    // tiles with the next item.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills, penalize shallow
    // placements that leave a non-tileable dead core.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — when the item consumes >= 80% of
        // the bin's residual, grant an escalating bonus that grows with
        // stream progress, targeting near-closures.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking — among bins that strand space below the
    // next item's size, prefer the one whose stranded remainder is closest
    // to being consumed by small items.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering — steeper escalation above 30% dead space,
    // small stability refund below 15%.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment — a placement whose post-residual matches
    // the aggregate open-residual pool closely keeps future small items
    // usable across bins; penalize drift that strands capacity.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening — among bins whose post-residual cannot
    // host the next item but is within a narrow miss window, prefer the
    // bin with the largest residual (closest to hosting).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting — prefer placements whose resulting
    // residual sits closest to the current mean residual, shrinking the
    // residual variance so future items tile the fleet uniformly.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement — when the pool is a sliver (mean
    // residual far below the next item's size), reward placements whose
    // post-residual RECOVERS toward the next item's size, steering the
    // mean residual back into a tileable band.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition — prefer placements that leave the
    // post-residual closest to the smallest viable residual band.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): dead-space saturation ramp — steeper cubic
    // escalation on the dead-space fraction once it exceeds the
    // tileability horizon (half the next item's size), with a salvage
    // credit for dead space within the horizon.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): fleet-dead-space drain — when the fleet is
    // drifting toward stranded capacity (mean residual far below the next
    // item's size), prefer placements that CLOSE a bin outright or leave
    // the smallest residual, actively draining stranded capacity.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 40): scarcity-tiered depth bonus — when only one or
    // two bins can host the item, deepen the reward for placements that
    // leave a residual exactly tileable by the next item.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 40): fresh-bin consolidation gate — when many bins are
    // open and the aggregate usable residual can still absorb the next
    // item somewhere, make opening a new bin costlier so compaction wins.
    if bin_residual == bin_capacity && open_bins_count >= 4 && next_item_size > 0 {
        let usable_pool = mean_residual * (open_bins_count as f64 - 1.0);
        if usable_pool >= next_item_size as f64 {
            score += 8.0 * (1.0 - 0.4 * progress) * ((usable_pool / (next_item_size as f64 * 3.0)).min(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless; relax the
        // fresh-bin penalty proportional to usable residual capacity.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor — continuous quadratic term on the
    // dead-space fraction, with a refund when the dead space exactly
    // tiles with the next item.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills, penalize shallow
    // placements that leave a non-tileable dead core.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — when the item consumes >= 80% of
        // the bin's residual, grant an escalating bonus that grows with
        // stream progress, targeting near-closures.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // MUTATION (gen 34): dead-space salvage ranking — among bins that
    // strand space below the next item's size, prefer the one whose
    // stranded remainder is closest to being consumed by small items.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // MUTATION (gen 34): dead-space ratio tiering — steeper escalation
    // above 30% dead space, small stability refund below 15%.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // MUTATION (gen 36): dead-space pool alignment — a placement whose
    // post-residual matches the aggregate open-residual pool closely
    // keeps future small items usable across bins; reward that alignment,
    // penalize residuals that drift away from the pool and thus strand
    // capacity no later item will likely consume. Scaled by open-bin
    // count since alignment only matters when alternatives exist.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        // Refund when the residual is a near-exact complement of the
        // next item, keeping the pool-aligned bin on the closure path.
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 36): residual-band sharpening — among bins whose
    // post-residual cannot host the next item but is within a narrow
    // miss window, prefer the bin with the largest residual (closest
    // to hosting), since it minimizes wasted capacity in the miss band.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 37): variance-collapse targeting — among placements
    // that leave a usable post-residual, prefer the one whose resulting
    // residual sits closest to the current mean residual, shrinking the
    // residual variance sigma_res so future items tile the fleet of
    // open bins uniformly. Weighted by scarcity of fitting options.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 37): residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 37): dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 38): variance-collapse refinement — when the pool
    // itself is a sliver (mean residual far below the next item's size),
    // the fleet is drifting toward dead space; counteract by rewarding
    // placements whose post-residual RECOVERS toward the next item's
    // size, steering the mean residual back into a tileable band instead
    // of letting it collapse onto unusable slivers.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // MUTATION (gen 38): residual-quantile competition — when several
    // bins can host the item, prefer the placement that leaves the
    // post-residual closest to the *smallest* viable residual band
    // (just under next_item_size) rather than the mean: small residual
    // variance alone can lock the fleet at a wasteful level, so add a
    // mild pull toward compact residuals when many bins remain open.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): dead-space saturation ramp — the diagnosed
    // weakness is residual/dead-space waste. Add a steeper cubic
    // escalation on the dead-space fraction once it exceeds the
    // tileability horizon (half the next item's size), so placements
    // that strand genuinely unusable capacity are pushed down hard,
    // while dead space that the next item can still consume is exempt.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        // Complementary salvage credit: dead space within the horizon is
        // cheap and may be consumed by small items — refund proportionally.
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): fleet-dead-space drain — track how much dead
    // space the fleet as a whole is accumulating (mean residual far
    // below the next item's size means most open bins are stranded).
    // When that happens, strongly prefer the placement that CLOSES a
    // bin outright (post_residual == 0) or leaves the smallest residual,
    // actively draining stranded capacity instead of spreading it.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 40): scarcity-tiered depth bonus — when only one or
    // two bins can host the item, deepen the reward for placements that
    // leave a residual exactly tileable by the next item, so scarce
    // capacity is spent on guaranteed closures rather than loose fits.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 41): pair-closure lookahead — beyond the next item,
    // estimate whether the post-residual can host a plausible PAIR of
    // upcoming items (next + a fraction of the mean item footprint).
    // Bins whose residual admits a two-item continuation are pulled up
    // sharply, while residuals that can host only the next item but
    // then strand a sub-horizon sliver are mildly demoted. This refines
    // the dead-space weakness by valuing residuals by their *future
    // throughput*, not just one-step tileability.
    if post_residual > 0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt + nxt * 0.5 {
            // Residual can plausibly host next item plus a half-size
            // follower: strong throughput credit, growing with progress.
            let depth = ((post_residual as f64 - nxt) / nxt).clamp(0.0, 2.0);
            score -= (4.0 + 3.0 * depth.min(1.0)) * (0.4 + 0.6 * progress);
        } else if post_residual >= next_item_size {
            let sliver = post_residual - next_item_size;
            if sliver > 0 && sliver < (next_item_size as f64 * 0.3).max(3.0) as u32 {
                score += 2.0 * (0.5 + 0.5 * progress);
            }
        }
    }

    // MUTATION (gen 41): best-bin competition sharpening — when the
    // fleet has many fitting bins, escalate the preference for the
    // TIGHTEST fit (largest consume_ratio) so that near-closures are
    // taken immediately rather than leaving many half-filled bins
    // competing for the same small items later.
    if bin_residual < bin_capacity && bin_residual >= item_size && fitting_bins_count >= 2 {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.9 {
            score -= 6.0 * (consume_ratio - 0.9) / 0.1 * (0.3 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding relief.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor (gen 30 mutation).
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
            if dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
                score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
            }
        }
    }

    // Consumption-efficiency coupling (gen 30 mutation).
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — escalate bonus for deep fills that
        // nearly close a bin, weighted by stream progress.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus (gen 30 mutation).
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics (gen 30 mutation).
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity (gen 30 mutation).
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // MUTATION (gen 40): dead-space saturation ramp — cubic escalation on
    // dead space beyond the tileability horizon (half the next item's
    // size), with a refund for dead space within the horizon that small
    // items can still consume. Directly attacks the diagnosed
    // residual/dead-space weakness.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 40): fleet-dead-space drain — when the mean residual
    // has collapsed far below the next item's size (fleet stranded),
    // prefer placements that close a bin outright or leave the smallest
    // residual, actively draining stranded capacity.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (dead / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 40): scarcity-tiered exact-tiling bonus — with one or
    // two fitting bins, reward placements whose post-residual is exactly
    // tileable by the next item so scarce capacity goes to closures.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 40): variance-collapse targeting — among placements
    // leaving a usable post-residual, prefer the one whose residual sits
    // closest to the current mean residual, shrinking residual variance
    // so future items tile the open fleet uniformly. Weighted by scarcity.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 40): near-closure miss-band ranking — among bins that
    // strand space just below the next item's size, prefer the largest
    // residual (closest to hosting), minimizing waste in the miss band.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
        // Orphan-floor gate: residuals stranding more than a quarter of
        // the next item are progressively penalized.
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 && post_residual > 4 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
