        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 43): residual-recovery steering when the pool has
    // collapsed below the next item's size.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / next_item_size as f64);
    }

    // MUTATION (gen 43): compact-residual pull under competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): consumption-efficiency coupling — deep fills
    // rewarded with escalation near closures.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): dead-space salvage ranking among stranded bins.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if dead * 2.0 >= next_item_size as f64 {
            score -= 2.5 * (dead / next_item_size as f64) * (1.0 - progress);
        }
    }

    // MUTATION (gen 43): exact-residual harmonics — multi-step closure.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // MUTATION (gen 43): dead-space-ratio governor — quadratic waste term
    // with tiering, refunding tileable dead space.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if waste_ratio > 0.30 {
            score += 14.0 * (waste_ratio - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if waste_ratio < 0.15 {
            score -= 3.0 * (0.15 - waste_ratio) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
            if (dead as u32) % next_item_size == 0 {
                score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
            }
        }
    }

    // MUTATION (gen 43): saturation ramp beyond the tileability horizon.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 43): cross-bin pair-closure lookahead — reward bins
    // whose stranded remainder plus the mean open pool could still host
    // the next item cooperatively.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if need > 0.0 && pool >= need * 0.9 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 43): shallow-fill anti-drift under fleet pressure.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = ((next_item_size as f64 - dead) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
            score += 3.0 * (shallow - 0.5) * stranded_frac * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Late-stream sliver hoarding — relax fresh-bin penalty when the
        // usable fleet residual is nearly exhausted.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
    }

    // Consumption-efficiency coupling — reward deep fills.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — item consumes >= 80% of residual.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Dead-space saturation ramp — cubic escalation beyond the tileability
    // horizon, refund below it.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Variance-collapse targeting — prefer post-residuals close to the
    // fleet mean residual, weighted by scarcity.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): cross-bin pair-closure lookahead — when this bin's
    // post-residual cannot host the next item but the fleet's smallest
    // residual pool could cover the remaining need, reward the cooperative
    // closure so the next item splits across open bins instead of forcing
    // a fresh one.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 43): endgame exact-closure sharpening — very late,
    // a placement leaving exactly the next item's size guarantees a
    // zero-dead-space follow-up; deepen the reward as progress nears 1.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 43): shallow-fill anti-drift — penalize placements that
    // consume less than half the residual AND strand space below the next
    // item when the fleet is still large.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): residual-band sharpening — among bins missing the
    // next item by a narrow window, prefer the largest residual (least
    // wasted space) rather than the smallest.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure — placing the item in a fresh bin
        // leaving exactly the next item's size closes perfectly.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding — near the end of the stream, open
        // bins with tiny residuals are nearly worthless; relax the
        // fresh-bin penalty proportional to usable residual capacity.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor — continuous quadratic term on the
    // dead-space fraction, with a refund when the dead space exactly
    // tiles with the next item.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills, penalize shallow
    // placements that leave a non-tileable dead core.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Near-perfect-fill coupling — when the item consumes >= 80% of
        // the bin's residual, grant an escalating bonus that grows with
        // stream progress, targeting near-closures.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition — reward the "hot band" just below the
    // next item's half-size threshold.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking — among bins that strand space below the
    // next item's size, prefer the one whose stranded remainder is closest
    // to being consumed by small items.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering — steeper escalation above 30% dead space,
    // small stability refund below 15%.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment — a placement whose post-residual matches
    // the aggregate open-residual pool closely keeps future small items
    // usable across bins.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening — among bins whose post-residual cannot
    // host the next item but is within a narrow miss window, prefer the
    // bin with the largest residual.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting — among placements that leave a usable
    // post-residual, prefer the one whose resulting residual sits closest
    // to the current mean residual.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement — when the pool itself is a sliver,
    // reward placements whose post-residual RECOVERS toward the next
    // item's size.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition — prefer the placement leaving the
    // post-residual closest to the smallest viable residual band.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp — steeper cubic escalation on the
    // dead-space fraction once it exceeds the tileability horizon.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain — prefer the placement that closes a bin
    // outright or leaves the smallest residual when the fleet is stranded.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus — tileable residuals under scarcity.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 42): cross-bin pair-closure lookahead — among bins
    // whose post-residual cannot host the next item, reward the one whose
    // stranded remainder combined with the smallest other open residual
    // could still host the next item (a two-bin cooperative closure),
    // since the next item can then be split across the fleet without
    // opening a fresh bin. Weighted by stream progress and scarcity.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 42): endgame exact-closure sharpening — very late in
    // the stream, a placement that leaves a residual exactly equal to the
    // next item's size guarantees a future zero-dead-space fill; deepen
    // the reward as progress approaches 1 so the final bins close tight.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 42): shallow-fill anti-drift — when the item consumes
    // less than half of the bin's residual AND the resulting post-residual
    // is stranded (below the next item), penalize proportionally to the
    // stranded fraction, but exempt the case where the fleet is nearly
    // closed (few open bins) since the damage is bounded there.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): dead-space ratio compaction refinement — the
    // diagnosed weakness is residual dead space. Strengthen the pull
    // toward placements whose post-residual fraction is minimal relative
    // to the fleet's mean dead fraction: reward bins that beat the mean
    // dead-space ratio, penalize those that exceed it, with the weight
    // sharpened mid-stream where consolidation choices matter most.
    if post_residual > 0 && bin_residual < bin_capacity {
        let dr = dead / cap;
        let fleet_dr = (mean_residual / cap).clamp(0.0, 1.0);
        let delta = dr - fleet_dr;
        let mid_weight = (1.0 - (2.0 * progress - 1.0).abs()).max(0.3);
        if delta < 0.0 {
            score -= 5.0 * (-delta) * mid_weight;
        } else {
            score += 4.0 * delta * mid_weight * (0.5 + 0.5 * progress);
        }
        // Absolute dead-space floor: any placement leaving a residual in
        // the 1..=4 sliver band is nearly closed — grant an escalating
        // reward that scales with how close the fleet is to exhaustion.
        if post_residual <= 4 {
            score -= (3.0 + 1.5 * (4 - post_residual) as f64) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): residual-efficiency coupling — when the next item
    // fits the post-residual with a tight margin (post-residual within
    // 1.5x of the next item), deepen the existing lookahead reward as a
    // function of scarcity of fitting bins, further reducing the dead
    // space left behind by near-exact fills.
    if next_item_size > 0 && post_residual >= next_item_size {
        let margin = post_residual as f64 / next_item_size as f64;
        if margin <= 1.5 {
            let tightness = 1.0 - (margin - 1.0) / 0.5;
            let scarcity = 1.0 - (fitting_bins_count as f64).min(4.0) / 4.0;
            score -= 4.0 * tightness * tightness * (0.3 + 0.7 * scarcity) * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 42): cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 42): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 42): shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): dead-space ceiling coupling — among bins that
    // fit the item, prefer the one whose post-residual is the LARGEST
    // still-tileable remainder when the fleet's aggregate dead space is
    // high; when aggregate dead space is low, prefer the smallest
    // post-residual (tightest fill). This steers residual variance down
    // in both regimes.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_dead = mean_residual * (open_bins_count as f64).max(1.0);
        let fleet_frac = (fleet_dead / (cap * open_bins_count.max(1) as f64)).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        if fleet_frac > 0.30 {
            // High aggregate dead space: keep large tileable remainders alive.
            if pr >= next_item_size as f64 && pr % next_item_size.max(1) as u32 == 0 {
                score -= 6.0 * (pr / cap) * (0.5 + 0.5 * progress);
            }
        } else {
            // Low aggregate dead space: reward tightest closures.
            let tight = 1.0 - (pr / cap);
            score -= 4.0 * tight * tight * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): sliver-merge preference — when the post-residual
    // is a tiny sliver (1..=4) the bin is effectively closed; grant an
    // escalating bonus scaled by how close the fleet mean residual is to
    // that sliver band, so near-closed bins absorb the item rather than
    // a bin that would strand a mid-sized remainder.
    if post_residual >= 1 && post_residual <= 4 && next_item_size > 0 {
        let band = ((next_item_size as f64 * 0.1).max(1.0)).min(4.0);
        if dead <= band {
            score -= 5.0 * (1.0 - dead / band) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): next-item consumption forecast — when the next
    // item exactly consumes the post-residual, the bin closes in two
    // steps with zero waste; deepen the reward under scarcity of fitting
    // bins, and add a mild penalty when the post-residual overshoots the
    // next item by a non-tileable margin late in the stream.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 42): cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 42): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 42): shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): dead-space ceiling coupling.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_dead = mean_residual * (open_bins_count as f64).max(1.0);
        let fleet_frac = (fleet_dead / (cap * open_bins_count.max(1) as f64)).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        if fleet_frac > 0.30 {
            if pr >= next_item_size as f64 && pr % next_item_size.max(1) as u32 == 0 {
                score -= 6.0 * (pr / cap) * (0.5 + 0.5 * progress);
            }
        } else {
            let tight = 1.0 - (pr / cap);
            score -= 4.0 * tight * tight * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): sliver-merge preference.
    if post_residual >= 1 && post_residual <= 4 && next_item_size > 0 {
        let band = ((next_item_size as f64 * 0.1).max(1.0)).min(4.0);
        if dead <= band {
            score -= 5.0 * (1.0 - dead / band) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): next-item consumption forecast.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    // MUTATION (gen 44): fleet-residual balancing — among bins that fit the
    // item, prefer the one whose post-residual is CLOSEST to the fleet mean
    // residual, scaled by how much the fleet's residual variance is already
    // low. This keeps residuals clustered so the next items can tile across
    // multiple bins simultaneously, reducing dead space fleet-wide.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 && open_bins_count >= 3 {
        let spread = ((dead - mean_residual).abs() / mean_residual.max(1.0)).clamp(0.0, 1.0);
        let balance = 1.0 - spread;
        score -= 4.5 * balance * balance * (0.35 + 0.65 * progress)
            * (1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64)).min(1.0) * 0.4);
        // Complementary penalty: bins whose post-residual drifts far from the
        // fleet mean strand unusable pockets when the stream is uniform.
        if spread > 0.6 {
            score += 2.5 * (spread - 0.6) / 0.4 * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // MUTATION (gen 44): two-bin exact-pair closure — when this bin's
    // post-residual plus the fleet mean residual exactly equals the next
    // item's size, placing the item here sets up a perfect two-bin split
    // next step; reward it strongly, strongest in mid-stream where there
    // is still time to exploit the pairing.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let need = next_item_size as f64 - dead;
        if need > 0.0 && (mean_residual - need).abs() <= 1.5 {
            let closeness = 1.0 - (mean_residual - need).abs() / 1.5;
            score -= 7.0 * closeness * closeness * (0.3 + 0.7 * (1.0 - progress * 0.5));
        }
    }

    // MUTATION (gen 44): fresh-bin residual-capacity check — opening a new
    // bin is only worth it if its post-residual (cap - item) is at least
    // as usable as the fleet's mean residual; otherwise the fleet's open
    // bins can absorb future items better. Penalize fresh bins whose
    // post-residual falls in the awkward band just below the next item.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count >= 1 {
        let fresh_rem = bin_capacity.saturating_sub(item_size);
        if fresh_rem > 0 && fresh_rem < next_item_size {
            let miss = (next_item_size - fresh_rem) as f64;
            if miss <= 8.0 {
                score += 6.0 * (1.0 - miss / 8.0) * (0.4 + 0.6 * progress);
            }
        }
        if fresh_rem >= next_item_size && mean_residual > fresh_rem as f64 {
            score += 4.0 * ((mean_residual - fresh_rem as f64) / cap).min(0.5) * 4.0 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 42): cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 42): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 42): shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): dead-space ceiling coupling.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_dead = mean_residual * (open_bins_count as f64).max(1.0);
        let fleet_frac = (fleet_dead / (cap * open_bins_count.max(1) as f64)).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        if fleet_frac > 0.30 {
            if pr >= next_item_size as f64 && pr % next_item_size.max(1) as u32 == 0 {
                score -= 6.0 * (pr / cap) * (0.5 + 0.5 * progress);
            }
        } else {
            let tight = 1.0 - (pr / cap);
            score -= 4.0 * tight * tight * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): sliver-merge preference.
    if post_residual >= 1 && post_residual <= 4 && next_item_size > 0 {
        let band = ((next_item_size as f64 * 0.1).max(1.0)).min(4.0);
        if dead <= band {
            score -= 5.0 * (1.0 - dead / band) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): next-item consumption forecast.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    // MUTATION (gen 44): fleet-variance compaction — among fitting bins,
    // sharpen the pull toward the fleet mean residual so residual variance
    // collapses; the pull is quadratic in the deviation and ramps with
    // progress, but is suppressed when the deviation is a perfect next-item
    // tile (those remainders are valuable).
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 44): dead-space budget gate — estimate the fleet's
    // remaining item volume vs. remaining open-bin capacity; when the
    // slack margin is thin, penalize any placement that strands more than
    // the next item's size (waste prevention), and reward exact closures
    // proportionally harder as the margin tightens.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): near-miss rescue refinement — when the next item
    // misses fitting here by only a sliver, the stranded space is nearly
    // recoverable elsewhere; penalize proportionally to how close the miss
    // is, so bins with a 1-2 unit miss sink below bins with a wide miss.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item,
    // with depth-2 and depth-3 chain anticipation (combined mutation).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        // Depth-3 chain: after hosting the next item, the remainder can
        // host it again (or close exactly) — a strong tiling signal.
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left <= 2 {
                score -= 12.0;
            } else if three_left < next_item_size {
                // Remainder after two next-items is a strand; penalize mildly.
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        // Half-recoverable strand is less harmful than a full strand.
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        // If this bin's own residual could host the next item after this
        // one, the strand is temporary — soften the penalty.
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
        if gap <= 5 {
            score -= 2.0 * (5 - gap) as f64 / 5.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                // Depth-3 fresh-bin tiling: room for two more next-items
                // with a tiny remainder.
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        // If the fleet's mean residual sits awkwardly close to the next
        // item's size (bins just barely miss), a fresh bin breaks the jam.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate: when existing bins would leave
        // nearly-exact-but-missed slack, opening fresh is costly.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand
        // half of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure: exact match with next item is far
        // more valuable when the fleet mean residual is misaligned.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding relief.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor: fresh bin that resets residuals
        // toward the next item's size when the fleet is spread out.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        // Strand just above the next item is a poor shape late.
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard: fraction of next item stranded.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    // Consumed-fraction weighted near-miss bump.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition: bins that leave below-half next-item
    // residuals are dead weight.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // Cross-bin pair-closure lookahead: when the next item misses here but
    // the fleet mean residual almost completes it, cooperative pairing is
    // viable — reward placements that keep that pairing alive.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // Endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // Shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): fleet-variance compaction — pull post-residuals
    // toward the fleet mean residual so variance collapses and future
    // items tile uniformly; suppress the pull for exact next-item tiles.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): dead-space budget gate — when the fleet's slack
    // margin is thin, penalize placements that strand more than the next
    // item's size and reward exact closures harder.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): near-miss rescue refinement — a 1-2 unit miss is
    // nearly recoverable elsewhere; rank such bins below wide misses.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): next-item consumption forecast — exact closure of
    // the next item is a strong signal, amplified under scarcity.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        // MUTATION (gen 44): three-step lookahead borrowed from best lineage.
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            } else if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
        // MUTATION (gen 44): near-miss rescue refinement — a 1-2 unit miss
        // strands nearly recoverable space; sink those bins below wide misses.
        if gap <= 2 {
            score += 6.0 * (2.0 - gap as f64) * (0.5 + 0.5 * progress);
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                // MUTATION (gen 44): two-tile fresh closure.
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand
        // half of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
                // MUTATION (gen 44): two-step fresh closure from best lineage.
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Late-stream sliver hoarding relief.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // MUTATION (gen 44): residual-variance governor on fresh bins.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-recovery steering.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress));
    }

    // Compact-residual pull under competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // MUTATION (gen 44): fleet-variance compaction — quadratic pull toward
    // the fleet mean residual, suppressed for perfect next-item tiles.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        let w = if is_tile { 2.5 } else { 10.0 };
        score += w * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
    }

    // MUTATION (gen 44): dead-space budget gate — when fleet slack margin
    // is thin, penalize placements that strand more than the next item.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 1 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 42): cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 42): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 42): shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): dead-space ceiling coupling.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_dead = mean_residual * (open_bins_count as f64).max(1.0);
        let fleet_frac = (fleet_dead / (cap * open_bins_count.max(1) as f64)).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        if fleet_frac > 0.30 {
            if pr >= next_item_size as f64 && pr % next_item_size.max(1) as u32 == 0 {
                score -= 6.0 * (pr / cap) * (0.5 + 0.5 * progress);
            }
        } else {
            let tight = 1.0 - (pr / cap);
            score -= 4.0 * tight * tight * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): sliver-merge preference.
    if post_residual >= 1 && post_residual <= 4 && next_item_size > 0 {
        let band = ((next_item_size as f64 * 0.1).max(1.0)).min(4.0);
        if dead <= band {
            score -= 5.0 * (1.0 - dead / band) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): next-item consumption forecast.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    // MUTATION (gen 44): fleet-variance compaction — among fitting bins,
    // sharpen the pull toward the fleet mean residual so residual variance
    // collapses; the pull is quadratic in the deviation and ramps with
    // progress, but is suppressed when the deviation is a perfect next-item
    // tile (those remainders are valuable).
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 44): dead-space budget gate — estimate the fleet's
    // remaining item volume vs. remaining open-bin capacity; when the
    // slack margin is thin, penalize any placement that strands more than
    // the next item's size (waste prevention), and reward exact closures
    // proportionally harder as the margin tightens.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): near-miss rescue refinement — when the next item
    // misses fitting here by only a sliver, the stranded space is nearly
    // recoverable elsewhere; penalize proportionally to how close the miss
    // is, so bins with a 1-2 unit miss sink below bins with a wide miss.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): dead-space ratio sharpening — dead space in the
    // 5-25 unit band is the dominant waste source; apply a smooth
    // bell-shaped penalty centered there, weighted by how badly the fleet
    // mean residual matches the next item (misaligned pools strand more).
    if post_residual > 0 && next_item_size > 0 {
        let band_center = 15.0f64.min(next_item_size as f64 * 0.6).max(5.0);
        let band_w = (band_center * 0.6 + 3.0).max(4.0);
        let dist = ((dead - band_center) / band_w).abs();
        if dist < 1.0 {
            let pool_mismatch = ((mean_residual - next_item_size as f64).abs()
                / next_item_size.max(1) as f64).clamp(0.0, 1.0);
            score += 4.5 * (1.0 - dist * dist) * (0.35 + 0.65 * pool_mismatch)
                * (0.4 + 0.6 * progress);
        }
        // Complementary reward: bins whose post-residual is within 2 units
        // of the next item's size eliminate nearly all dead space on the
        // following step; deepen the existing exact-closure pull mid-stream.
        let near_exact = (dead - next_item_size as f64).abs();
        if near_exact <= 2.0 && fitting_bins_count <= 4 {
            score -= (3.0 + 2.0 * (2.0 - near_exact))
                * (1.0 - (fitting_bins_count as f64) / 4.0)
                * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 45): residual-efficiency ramp — reward placements whose
    // consumed fraction of the bin's residual is high, with a smooth ramp
    // instead of the hard 0.7 threshold, so near-threshold fills also gain
    // compaction pressure; suppressed when the leftover is an exact tile.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0 {
        let consume = item_size as f64 / bin_residual as f64;
        let is_tile = next_item_size > 0 && post_residual % next_item_size == 0;
        let ramp = ((consume - 0.5) / 0.5).clamp(0.0, 1.0);
        if !is_tile {
            score -= 3.0 * ramp * ramp * (0.3 + 0.7 * progress);
        } else {
            score -= 1.5 * ramp * ramp * (0.3 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 42): cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 42): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 42): shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): dead-space ceiling coupling.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_dead = mean_residual * (open_bins_count as f64).max(1.0);
        let fleet_frac = (fleet_dead / (cap * open_bins_count.max(1) as f64)).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        if fleet_frac > 0.30 {
            if pr >= next_item_size as f64 && pr % next_item_size.max(1) as u32 == 0 {
                score -= 6.0 * (pr / cap) * (0.5 + 0.5 * progress);
            }
        } else {
            let tight = 1.0 - (pr / cap);
            score -= 4.0 * tight * tight * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): sliver-merge preference.
    if post_residual >= 1 && post_residual <= 4 && next_item_size > 0 {
        let band = ((next_item_size as f64 * 0.1).max(1.0)).min(4.0);
        if dead <= band {
            score -= 5.0 * (1.0 - dead / band) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): next-item consumption forecast.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    // MUTATION (gen 44): fleet-variance compaction — among fitting bins,
    // sharpen the pull toward the fleet mean residual so residual variance
    // collapses; the pull is quadratic in the deviation and ramps with
    // progress, but is suppressed when the deviation is a perfect next-item
    // tile (those remainders are valuable).
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 44): dead-space budget gate — estimate the fleet's
    // remaining item volume vs. remaining open-bin capacity; when the
    // slack margin is thin, penalize any placement that strands more than
    // the next item's size (waste prevention), and reward exact closures
    // proportionally harder as the margin tightens.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): near-miss rescue refinement — when the next item
    // misses fitting here by only a sliver, the stranded space is nearly
    // recoverable elsewhere; penalize proportionally to how close the miss
    // is, so bins with a 1-2 unit miss sink below bins with a wide miss.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): dead-space-ratio minimization — the diagnosed
    // weakness is residual dead space. Rank placements by the exact
    // fraction of the bin that ends up stranded, with a superlinear ramp
    // so mid-size dead zones are punished harder, gated by whether the
    // stranded remainder can plausibly host the next item.
    if post_residual > 0 {
        let dead_frac = dead / cap;
        let tileable = next_item_size > 0 && dead >= next_item_size as f64
            && (dead as u32) % next_item_size == 0;
        let gate = if tileable { 0.35 } else { 1.0 };
        score += 16.0 * dead_frac * dead_frac * gate * (0.45 + 0.55 * progress);
        // Complementary reward: bins whose post-residual is the smallest
        // plausible remainder band (just above next item) get pulled down.
        if next_item_size > 0 && post_residual >= next_item_size {
            let over = dead - next_item_size as f64;
            if over <= 3.0 {
                score -= (3.0 - over) * 2.0 * (0.5 + 0.5 * progress) * gate;
            }
        }
        // Fresh-bin coupling: when the fleet's mean dead fraction is high,
        // opening a fresh bin that tiles exactly is preferable to dumping
        // into a fragmented bin; when low, keep consolidating.
        if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count >= 1 {
            let fleet_dead_frac = (mean_residual / cap).clamp(0.0, 1.0);
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem >= next_item_size {
                let fresh_slack = fresh_rem - next_item_size;
                if fleet_dead_frac > 0.25 && fresh_slack <= 4 {
                    score -= 9.0 * (fleet_dead_frac - 0.25) / 0.75 * (0.4 + 0.6 * progress);
                } else if fleet_dead_frac < 0.10 && fresh_slack > 8 {
                    score += 6.0 * (0.10 - fleet_dead_frac) / 0.10 * (1.0 - progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        // MUTATION (gen 44): depth-2 lookahead — reward a residual that can
        // host the next item AND then still host a second copy or the item
        // size, i.e. a chain of closures.
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
        // MUTATION (gen 44): prefer the largest residual in the miss band.
        if gap <= 5 {
            score -= 2.0 * (5.0 - gap as f64) / 5.0 * (1.0 - progress);
        }
        // MUTATION (gen 44): near-miss rescue — a 1-2 unit miss is almost
        // recoverable elsewhere; sink such bins below wide misses.
        if gap <= 2 {
            score += 6.0 * (2.0 - gap as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                // MUTATION (gen 44): depth-2 fresh-bin tiling.
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        // MUTATION (gen 44): awkward-fit gate — when the fleet's mean
        // residual is within a couple units of the next item, open bins
        // are nearly usable; avoid spawning a fresh bin.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand
        // half of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
                // MUTATION (gen 44): exact two-step fresh closure, sharpened
                // by how far the fleet mean residual is from that target.
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Late-stream sliver hoarding relief.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // MUTATION (gen 44): residual-variance governor for fresh bins —
        // when the fresh remainder diverges from the fleet mean residual,
        // opening the bin worsens variance; reward the divergence relief.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    // Variance-collapse targeting — prefer placements whose resulting
    // residual sits closest to the current mean residual, shrinking
    // residual variance so future items tile the fleet uniformly.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-recovery steering — when the fleet's mean residual has
    // collapsed below the next item's size, reward placements whose
    // post-residual recovers toward a tileable band.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress));
    }

    // Compact-residual pull — when many bins compete, mildly prefer
    // leaving residuals just under the next item's size.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling — reward deep fills of the bin's
    // residual, with escalation near closures.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
        // MUTATION (gen 44): shallow-fill anti-drift — penalize shallow
        // consumption that strands more than the next item's size when
        // many bins are open.
        if consume_ratio < 0.5 && post_residual > 0 && next_item_size > 0
            && post_residual < next_item_size && open_bins_count >= 4 {
            let shallow = 1.0 - consume_ratio;
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5).max(0.0) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space salvage ranking — among bins that strand space below the
    // next item, prefer the one whose stranded remainder is closest to the
    // mean residual pool.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
    }

    // Exact-residual harmonics — guaranteed multi-step closure reward when
    // the post-residual tiles with the next item.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
        // MUTATION (gen 44): harmonic depth pull — pull harder toward
        // multi-tile remainders so chains of next-item placements close.
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // MUTATION (gen 44): fleet-variance compaction — among fitting bins,
    // sharpen the pull toward the fleet mean residual so residual variance
    // collapses; the pull is quadratic in the deviation and ramps with
    // progress, but is suppressed when the deviation is a perfect next-item
    // tile (those remainders are valuable).
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 44): dead-space budget gate — estimate the fleet's
    // remaining item volume vs. remaining open-bin capacity; when the
    // slack margin is thin, penalize any placement that strands more than
    // the next item's size (waste prevention), and reward exact closures
    // proportionally harder as the margin tightens.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 44): cross-bin pair-closure lookahead — when the next
    // item cannot fit here, but the fleet's mean residual pool nearly
    // covers the missing amount, a cooperative split placement exists;
    // reward bins that leave the complementary share.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
            if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
                score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
            }
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // Cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // Endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // Shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space ceiling coupling.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_dead = mean_residual * (open_bins_count as f64).max(1.0);
        let fleet_frac = (fleet_dead / (cap * open_bins_count.max(1) as f64)).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        if fleet_frac > 0.30 {
            if pr >= next_item_size as f64 && pr % next_item_size.max(1) as u32 == 0 {
                score -= 6.0 * (pr / cap) * (0.5 + 0.5 * progress);
            }
        } else {
            let tight = 1.0 - (pr / cap);
            score -= 4.0 * tight * tight * (0.4 + 0.6 * progress);
        }
    }

    // Sliver-merge preference.
    if post_residual >= 1 && post_residual <= 4 && next_item_size > 0 {
        let band = ((next_item_size as f64 * 0.1).max(1.0)).min(4.0);
        if dead <= band {
            score -= 5.0 * (1.0 - dead / band) * (0.3 + 0.7 * progress);
        }
    }

    // Next-item consumption forecast.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    // MUTATION (gen 44): fleet-variance compaction — quadratic pull toward
    // the fleet mean residual, suppressed for perfect next-item tiles.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 44): dead-space budget gate — margin-aware waste penalty.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): near-miss rescue refinement.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): tight-fit depth cascade — combine fine-grained
    // residual fitting with lookahead anticipation: when the item nearly
    // exhausts the residual AND the leftover still tiles with the next
    // item, escalate the reward so deep, chain-compatible placements
    // dominate over mediocre multi-bin fits.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0 && next_item_size > 0 {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.5 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= (4.0 + 8.0 * consume_ratio) * (0.4 + 0.6 * progress);
        }
        // Chain closure: residual exactly equals next + current sizes.
        if post_residual == item_size + next_item_size {
            score -= 10.0 * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): fleet-slack fresh-bin governor — open a new bin
    // only when the fleet's total residual cannot plausibly absorb the
    // remaining stream; otherwise tighten the fresh-bin penalty so
    // existing capacity gets consolidated first.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let absorbable = (fleet_res / next_item_size.max(1) as f64).floor();
        if absorbable >= 2.0 {
            score += 8.0 * ((absorbable - 2.0).min(3.0) / 3.0) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = 0.0f64;
    let dead = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && dead < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = dead - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = dead / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((dead - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // MUTATION (gen 42): cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 42): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 42): shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 43): dead-space ceiling coupling.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_dead = mean_residual * (open_bins_count as f64).max(1.0);
        let fleet_frac = (fleet_dead / (cap * open_bins_count.max(1) as f64)).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        if fleet_frac > 0.30 {
            if pr >= next_item_size as f64 && pr % next_item_size.max(1) as u32 == 0 {
                score -= 6.0 * (pr / cap) * (0.5 + 0.5 * progress);
            }
        } else {
            let tight = 1.0 - (pr / cap);
            score -= 4.0 * tight * tight * (0.4 + 0.6 * progress);
        }
    }

    // MUTATION (gen 43): sliver-merge preference.
    if post_residual >= 1 && post_residual <= 4 && next_item_size > 0 {
        let band = ((next_item_size as f64 * 0.1).max(1.0)).min(4.0);
        if dead <= band {
            score -= 5.0 * (1.0 - dead / band) * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 43): next-item consumption forecast.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    // MUTATION (gen 44): fleet-variance compaction — among fitting bins,
    // sharpen the pull toward the fleet mean residual so residual variance
    // collapses; the pull is quadratic in the deviation and ramps with
    // progress, but is suppressed when the deviation is a perfect next-item
    // tile (those remainders are valuable).
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 44): dead-space budget gate — estimate the fleet's
    // remaining item volume vs. remaining open-bin capacity; when the
    // slack margin is thin, penalize any placement that strands more than
    // the next item's size (waste prevention), and reward exact closures
    // proportionally harder as the margin tightens.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): near-miss rescue refinement — when the next item
    // misses fitting here by only a sliver, the stranded space is nearly
    // recoverable elsewhere; penalize proportionally to how close the miss
    // is, so bins with a 1-2 unit miss sink below bins with a wide miss.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): dead-space ratio ramp — the diagnosed weakness is
    // residual dead-space ratio; add a convex escalating penalty on the
    // post-placement dead-space fraction that steepens in the mid/late
    // stream, but exempt tiny remainders that are recoverable by the next
    // item or by fleet pairing (those were already rewarded above).
    if post_residual > 0 {
        let dr = dead / cap;
        let exempt = next_item_size > 0 && (post_residual >= next_item_size
            || dead <= (next_item_size as f64 * 0.15).max(1.0));
        if !exempt {
            score += (10.0 + 14.0 * progress) * dr * dr * dr;
        }
        // Complementary reward: bins that leave the fleet-mean dead space
        // (harmonized remainders) get a mild pull so variance keeps falling
        // without fighting the tile bonuses.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let harm = 1.0 - ((dead - mean_residual) / mean_residual.max(1.0)).abs().clamp(0.0, 1.0);
            score -= 2.0 * harm * harm * (0.3 + 0.7 * progress);
        }
        // Mid-band dead-space shaping: remainders just above the next item
        // but under 1.5x strand recoverable space; nudge them down gently
        // so they rank below near-exact fits.
        if next_item_size > 0 && post_residual > next_item_size && dead < 1.5 * next_item_size as f64 {
            let over_frac = (dead - next_item_size as f64) / (0.5 * next_item_size as f64);
            score += 2.5 * over_frac * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    // Dead-space penalty, sharpened when residual is a tiny sliver.
    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    // Lookahead: reward bins whose post-residual hosts the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize stranded space, worse late.
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Consolidation pressure grows with open-bin count.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    // Mean-residual comparison: tight bins are good targets.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    // New-bin candidate shaping.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        // Dead-space-aware fresh-bin gate.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        // Fragment-waste gate: fresh bin cheaper when open bins strand half
        // of the next item's size.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        // Large-item fresh-bin relief late in the stream.
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee.
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    // Residual curvature shaping.
    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    // Global waste guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
        if next_item_size > 0 && dead >= next_item_size as f64 && (dead as u32) % next_item_size == 0 {
            score -= 9.0 * waste_ratio * (0.4 + 0.6 * progress);
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // Residual-band competition.
    if next_item_size > 0 && fitting_bins_count >= 2 && post_residual > 0 {
        let hot_lo = (next_item_size as f64 * 0.5).max(1.0);
        if dead < hot_lo {
            score -= 4.0 * (1.0 - dead / hot_lo);
        }
    }

    // Mid-residual compaction pull.
    if post_residual >= 10 && dead <= 0.25 * cap && open_bins_count > 4 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress) * (1.0 - dead / (0.25 * cap));
    }

    // Dead-space salvage ranking.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = dead;
        let pool = mean_residual.max(1.0);
        let match_closeness = 1.0 - ((stranded - pool).abs() / pool).clamp(0.0, 1.0);
        let salvage = 5.0 * match_closeness * (0.4 + 0.6 * progress);
        let orphan = 4.0 * (1.0 - match_closeness) * (1.0 - 0.5 * progress);
        score += orphan - salvage;
        if stranded * 2 >= next_item_size as f64 {
            score -= 2.5 * (stranded / next_item_size as f64) * (1.0 - progress);
        }
    }

    // Dead-space ratio tiering.
    if post_residual > 0 {
        let dr = dead / cap;
        if dr > 0.30 {
            score += 14.0 * (dr - 0.30) / 0.70 * (0.5 + 0.5 * progress);
        } else if dr < 0.15 {
            score -= 3.0 * (0.15 - dr) / 0.15 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Dead-space pool alignment.
    if post_residual > 0 && open_bins_count >= 2 && bin_residual < bin_capacity {
        let pool = mean_residual.max(1.0);
        let align = 1.0 - ((dead - pool).abs() / cap).clamp(0.0, 1.0);
        let weight = ((open_bins_count as f64).ln().max(1.0) / 4.0).min(1.0);
        score += (1.0 - align) * 3.5 * weight * (0.6 + 0.4 * progress);
        if next_item_size > 0 {
            let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
            if gap <= 2.0 {
                score -= (4.0 - gap) * weight * (0.5 + 0.5 * progress);
            }
        }
    }

    // Residual-band sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score -= 2.0 * (5.0 - miss) / 5.0 * (1.0 - progress);
        }
    }

    // Variance-collapse targeting.
    if post_residual > 0 && bin_residual < bin_capacity && fitting_bins_count >= 2 {
        let pool = mean_residual.max(1.0);
        let closeness = 1.0 - ((dead - pool).abs() / pool).clamp(0.0, 1.0);
        let scarcity = 1.0 - (fitting_bins_count as f64).min(6.0) / 6.0;
        score -= 4.5 * closeness * closeness * (0.5 + 0.5 * scarcity) * (0.4 + 0.6 * progress);
    }

    // Residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    // Dead-space floor gate.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 4 {
        let orphan_frac = post_residual as f64 / next_item_size as f64;
        if orphan_frac > 0.25 {
            score += 3.0 * (orphan_frac - 0.25) / 0.75 * (0.3 + 0.7 * progress);
        }
    }

    // Variance-collapse refinement.
    if post_residual > 0 && next_item_size > 0 && mean_residual < next_item_size as f64 {
        let deficit = next_item_size as f64 - mean_residual;
        let recovery = ((post_residual as f64 - mean_residual) / deficit.max(1.0)).clamp(0.0, 1.0);
        score -= 3.0 * recovery * (0.5 + 0.5 * (1.0 - progress)) * (1.0 - deficit / (next_item_size as f64));
    }

    // Residual-quantile competition.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 && open_bins_count >= 5 {
        let over = (post_residual - next_item_size) as f64;
        if over > 0.0 && over <= next_item_size as f64 * 0.5 {
            score -= 2.5 * (1.0 - over / (next_item_size as f64 * 0.5)) * (0.4 + 0.6 * progress);
        }
    }

    // Dead-space saturation ramp.
    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        }
        if dead <= horizon {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-dead-space drain.
    if post_residual > 0 && next_item_size > 0 && open_bins_count >= 3 {
        let stranded_frac = ((next_item_size as f64 - mean_residual) / next_item_size.max(1) as f64).clamp(0.0, 1.0);
        if stranded_frac > 0.4 {
            let drain = (post_residual as f64 / cap).clamp(0.0, 1.0);
            score += 6.0 * stranded_frac * drain * (0.3 + 0.7 * progress);
        }
    }

    // Scarcity-tiered depth bonus.
    if next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && post_residual % next_item_size == 0 {
        score -= (4.0 + 4.0 * (2 - fitting_bins_count) as f64) * (0.4 + 0.6 * progress);
    }

    // Cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // Endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // Shallow-fill anti-drift.
    if bin_residual < bin_capacity && bin_residual >= item_size && post_residual > 0
        && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 4 {
        let shallow = 1.0 - (item_size as f64 / bin_residual as f64);
        if shallow > 0.5 {
            let stranded_frac = (next_item_size as f64 - dead) / next_item_size.max(1) as f64;
            score += 3.0 * (shallow - 0.5) * stranded_frac.clamp(0.0, 1.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space ceiling coupling.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 1 {
        let fleet_dead = mean_residual * (open_bins_count as f64).max(1.0);
        let fleet_frac = (fleet_dead / (cap * open_bins_count.max(1) as f64)).clamp(0.0, 1.0);
        let pr = post_residual as f64;
        if fleet_frac > 0.30 {
            if pr >= next_item_size as f64 && pr % next_item_size.max(1) as u32 == 0 {
                score -= 6.0 * (pr / cap) * (0.5 + 0.5 * progress);
            }
        } else {
            let tight = 1.0 - (pr / cap);
            score -= 4.0 * tight * tight * (0.4 + 0.6 * progress);
        }
    }

    // Sliver-merge preference.
    if post_residual >= 1 && post_residual <= 4 && next_item_size > 0 {
        let band = ((next_item_size as f64 * 0.1).max(1.0)).min(4.0);
        if dead <= band {
            score -= 5.0 * (1.0 - dead / band) * (0.3 + 0.7 * progress);
        }
    }

    // Next-item consumption forecast.
    if next_item_size > 0 && post_residual == next_item_size {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(5.0) / 5.0;
        score -= 6.0 + 10.0 * scarcity;
    } else if next_item_size > 0 && post_residual > next_item_size && progress > 0.65 {
        let over = post_residual - next_item_size;
        if over % next_item_size != 0 && over < next_item_size {
            score += 3.0 * (over as f64 / next_item_size as f64) * (progress - 0.65) / 0.35;
        }
    }

    // MUTATION (gen 44): fleet-variance compaction — among fitting bins,
    // sharpen the pull toward the fleet mean residual so residual variance
    // collapses; the pull is quadratic in the deviation and ramps with
    // progress, but is suppressed when the deviation is a perfect next-item
    // tile (those remainders are valuable).
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 44): dead-space budget gate — estimate the fleet's
    // remaining item volume vs. remaining open-bin capacity; when the
    // slack margin is thin, penalize any placement that strands more than
    // the next item's size (waste prevention), and reward exact closures
    // proportionally harder as the margin tightens.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 44): near-miss rescue refinement — when the next item
    // misses fitting here by only a sliver, the stranded space is nearly
    // recoverable elsewhere; penalize proportionally to how close the miss
    // is, so bins with a 1-2 unit miss sink below bins with a wide miss.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual == item_size {
        score -= 15.0;
    }

    let dead = post_residual as f64;
    let dead_threshold = 10.0f64.max(next_item_size as f64 * 0.5);
    score += 0.15 * dead * dead / cap;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        let urgency = 1.0 + 0.5 * (1.0 - progress);
        score += (18.0 + 0.5 * (dead_threshold - dead)) * urgency;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
        let two_left = post_residual - next_item_size;
        if two_left == 0 {
            score -= 30.0;
        } else if two_left <= 3 {
            score -= 12.0;
        } else if two_left == item_size {
            score -= 18.0;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left <= 2 {
                score -= 12.0;
            }
        }
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        if fit_ratio > 0.6 {
            score -= 8.0 * (fit_ratio - 0.6) / 0.4;
        }
        if two_left > 3 && post_residual % next_item_size == 0 {
            score -= 6.0 + 0.05 * post_residual as f64;
        }
        if two_left >= next_item_size {
            let three_left = two_left - next_item_size;
            if three_left == 0 {
                score -= 20.0;
            } else if three_left == item_size {
                score -= 10.0;
            } else if three_left > 0 && three_left < next_item_size {
                score += 2.0 * (three_left as f64) / (next_item_size as f64);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size - post_residual;
        score += 4.0 + 0.8 * gap.min(20) as f64;
        if gap <= 6 && fitting_bins_count <= 2 {
            score += 8.0 + 1.5 * (6 - gap) as f64;
        }
        if post_residual * 2 >= next_item_size {
            score += 3.0;
        }
        if bin_residual >= item_size && (bin_residual - item_size) >= next_item_size {
            score += 5.0 + 0.1 * next_item_size as f64;
        }
        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
    }

    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 2.0 * pressure.min(4.0);

    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }
    let dev = post_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        if dev < 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.2 * dev;
        }
    }

    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let fresh_fill = item_size as f64 / cap;
        let mut penalty = 40.0
            - 0.3 * item_size as f64
            - 25.0 * tightness
            - 10.0 * progress;

        if fresh_fill > 0.75 {
            penalty -= 18.0 * (fresh_fill - 0.75) / 0.25;
        }
        if fresh_fill > 0.55 && fresh_fill <= 0.75 {
            let mid_bonus = 10.0 * (fresh_fill - 0.55) / 0.20;
            penalty -= if progress < 0.55 { mid_bonus } else { 0.35 * mid_bonus };
        }
        if next_item_size > 0 {
            let fresh_two = bin_capacity.saturating_sub(item_size);
            if fresh_two >= next_item_size {
                let fresh_slack = fresh_two - next_item_size;
                if fresh_slack <= 5 {
                    penalty -= 14.0 - 1.5 * fresh_slack as f64;
                } else if fresh_slack <= 12 {
                    penalty -= 4.0;
                }
                if fresh_slack > 5 && fresh_two % next_item_size == 0 {
                    penalty -= 6.0;
                }
                if fresh_two >= 2 * next_item_size {
                    let fresh_three = fresh_two - 2 * next_item_size;
                    if fresh_three <= 4 {
                        penalty -= 10.0;
                    }
                }
            }
            if item_size as u64 + next_item_size as u64 <= bin_capacity as u64 {
                let fresh_left = bin_capacity - item_size - next_item_size;
                if fresh_left <= 4 {
                    penalty -= 18.0;
                }
                if fresh_left == item_size as u64 {
                    penalty -= 12.0;
                }
            }
        }
        let mr = mean_residual.max(0.0);
        if mr > cap * 0.35 && fresh_fill > 0.5 {
            penalty -= 6.0 * ((mr / cap) - 0.35).min(0.3) * 10.0;
        } else if mr < cap * 0.15 && fresh_fill < 0.4 {
            penalty += 5.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress > 0.7 {
            penalty += 15.0;
        }
        if fitting_bins_count >= 3 {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let awkward = (mean_residual - (next_item_size as f64)).abs();
            if awkward < 3.0 {
                penalty += 8.0;
            }
        }
        if fitting_bins_count <= 1 && mr < cap * 0.25 {
            penalty += 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_slack = mean_residual - (next_item_size as f64);
            if best_slack >= -2.0 && best_slack <= 4.0 {
                penalty += 12.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let strand = (next_item_size as f64 - mean_residual).max(0.0);
            if strand > (next_item_size as f64) * 0.5 {
                penalty -= 10.0 * (strand / next_item_size.max(1) as f64).min(1.5)
                    * (0.4 + 0.6 * (1.0 - progress));
            }
        }
        let big_frac = item_size as f64 / cap;
        if big_frac > 0.6 && progress > 0.5 {
            penalty -= 9.0 * ((big_frac - 0.6) / 0.4) * ((progress - 0.5) / 0.5);
        }
        // Fresh-bin remainder tiling guarantee (borrowed from best).
        if next_item_size >= 2 {
            let fresh_rem = bin_capacity.saturating_sub(item_size);
            if fresh_rem == next_item_size {
                penalty -= 22.0 * (0.5 + 0.5 * progress);
            } else if fresh_rem > next_item_size && fresh_rem % next_item_size == 0 {
                let tiles = fresh_rem / next_item_size;
                if tiles <= 3 {
                    penalty -= (10.0 + 4.0 * (3 - tiles) as f64) * (0.4 + 0.6 * progress);
                }
            }
        }
        // Mean-residual anchoring.
        let mr_frac = mr / cap;
        if mr_frac < 0.12 {
            penalty -= 7.0 * (0.12 - mr_frac) / 0.12 * (0.5 + 0.5 * progress);
        } else if mr_frac > 0.45 {
            penalty += 6.0 * (mr_frac - 0.45).min(0.3) * 10.0;
        }
        // Two-step fresh-bin closure.
        if next_item_size > 0 && bin_capacity > item_size {
            let fresh_rem = bin_capacity - item_size;
            if fresh_rem == next_item_size {
                let mismatch = ((mean_residual - next_item_size as f64).abs()) / cap;
                penalty -= 12.0 + 28.0 * mismatch.min(0.5);
            }
        }
        // Late-stream sliver hoarding.
        if progress > 0.6 {
            let usable = (mr * fitting_bins_count as f64) / cap;
            if usable < 1.5 {
                penalty -= 10.0 * (1.5 - usable) * (progress - 0.6) / 0.4;
            }
        }
        // Residual-variance governor.
        if fitting_bins_count >= 2 && next_item_size > 0 {
            let spread = ((mean_residual - (cap - item_size as f64)).abs()) / cap;
            if spread > 0.1 && fresh_fill > 0.4 {
                penalty -= 8.0 * spread.min(0.5) * (0.3 + 0.7 * progress);
            }
        }
        score += penalty;
    }

    let r = post_residual as f64 / cap;
    score += 8.0 * r * r;
    if post_residual > 0 {
        score -= 14.0 * (1.0 - (r * 4.0).min(1.0).sqrt());
        if post_residual <= 9 {
            score -= 2.0 * (10 - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
            let strand_amt = (post_residual - next_item_size) as f64;
            if strand_amt > 2.0 {
                score += (1.5 + 3.0 * progress) * (strand_amt / next_item_size.max(1) as f64).min(1.0) * 6.0;
            }
        }
        if progress > 0.6 && post_residual <= 15 {
            score -= 3.0 * (1.0 - progress);
        }
    }
    if next_item_size > post_residual && post_residual > 0 && r < 0.15 {
        score += 6.0 + 30.0 * r;
    }
    if progress > 0.8 && post_residual > 0 {
        score += 4.0 * progress * r;
    }
    if next_item_size > 0 && post_residual == item_size + next_item_size {
        score -= 22.0;
    }
    if post_residual >= item_size && post_residual <= item_size + 8 {
        score -= 8.0;
    }
    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let waste_frac = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 3.0 * waste_frac * (1.0 - progress);
    }

    if post_residual > 0 && item_size >= 2 && post_residual % item_size == 0 && post_residual / item_size <= 3 {
        score -= 6.0;
    }

    if progress > 0.85 && post_residual > 0 {
        score += 5.0 * (post_residual.min(30) as f64) * progress * 0.2;
    }

    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        score -= 10.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let orig_res = bin_residual as f64;
        if orig_res > 0.0 {
            let consumed_frac = (item_size as f64 / orig_res).clamp(0.0, 1.0);
            let gap = (next_item_size - post_residual) as f64;
            let bump = gap * (gap / next_item_size.max(1) as f64);
            score += 2.5 * bump * consumed_frac * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    if post_residual >= 1 && post_residual <= 3 {
        score -= (4.0 + 2.0 * (4 - post_residual) as f64) * (0.4 + 0.6 * progress);
    }

    if fitting_bins_count >= 3 && post_residual > 0 {
        let match_bonus = 6.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0));
        score -= match_bonus * 0.5;
    }

    // Dead-space-ratio governor.
    if post_residual > 0 {
        let waste_ratio = dead / cap;
        score += 22.0 * waste_ratio * waste_ratio * (1.0 - 0.35 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_left = post_residual - next_item_size;
            if two_left > 0 && two_left <= 4 {
                score -= 3.0 + 0.5 * (4 - two_left) as f64;
            }
        }
    }

    // Consumption-efficiency coupling.
    if bin_residual < bin_capacity && bin_residual >= item_size {
        let consume_ratio = item_size as f64 / bin_residual as f64;
        if consume_ratio > 0.7 {
            let depth = (consume_ratio - 0.7) / 0.3;
            score -= 7.0 * depth * (0.6 + 0.4 * progress);
        } else if consume_ratio < 0.25 && post_residual > 0 && next_item_size > 0 && post_residual != next_item_size {
            if post_residual % next_item_size.max(1) != 0 {
                score += 4.0 * (0.25 - consume_ratio) / 0.25 * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Extra deep-fill escalation.
        if consume_ratio >= 0.80 {
            let depth = (consume_ratio - 0.80) / 0.20;
            score -= (8.0 + 12.0 * depth) * (0.4 + 0.6 * progress);
        }
    }

    // Scarcity-aware deep-fill bonus.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let depth_bonus = 6.0 * (1.0 - (fitting_bins_count as f64 / 3.0));
        score -= depth_bonus * (0.5 + 0.5 * progress);
    }

    // Exact-residual harmonics.
    if next_item_size >= 2 && post_residual > 0 && post_residual % next_item_size == 0 {
        let tiles = post_residual / next_item_size;
        if tiles <= 4 {
            score -= (5.0 + 2.0 * (4 - tiles) as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Two-step closure bonus under scarcity.
    if next_item_size > 0 && bin_residual == item_size + next_item_size && fitting_bins_count <= 3 {
        score -= 14.0 + 3.0 * (3 - fitting_bins_count.min(3)) as f64;
    }

    // MUTATION (gen 45): fleet-variance compaction — pull fitting bins'
    // post-residual toward the fleet mean so residual variance collapses,
    // softened when the remainder is a perfect next-item tile.
    if post_residual > 0 && next_item_size > 0 && fitting_bins_count >= 2 {
        let dev_norm = (dead - mean_residual) / cap;
        let is_tile = post_residual % next_item_size == 0;
        if !is_tile {
            score += 10.0 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        } else {
            score += 2.5 * dev_norm * dev_norm.abs() * (0.3 + 0.7 * progress);
        }
    }

    // MUTATION (gen 45): dead-space budget gate — when fleet slack margin is
    // thin, penalize placements that strand more than the next item's size,
    // and reward exact closures harder as the margin tightens.
    if post_residual > 0 && next_item_size > 0 {
        let fleet_cap = open_bins_count as f64 * cap;
        let fleet_res = mean_residual * open_bins_count.max(1) as f64;
        let used_frac = ((fleet_cap - fleet_res) / fleet_cap.max(1.0)).clamp(0.0, 1.0);
        let margin = 1.0 - used_frac;
        if dead > next_item_size as f64 {
            let over = dead - next_item_size as f64;
            score += 4.0 * (over / cap) * (1.0 - margin) * (0.4 + 0.6 * progress);
        } else if dead == 0.0 {
            score -= 3.0 * (1.0 - margin) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): near-miss rescue refinement — a 1-2 unit miss is
    // nearly recoverable elsewhere; penalize more than wide misses.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 2.0 {
            score += 6.0 * (2.0 - miss) * (0.5 + 0.5 * progress);
        }
    }

    // MUTATION (gen 45): endgame exact-closure sharpening.
    if next_item_size > 0 && post_residual == next_item_size && progress > 0.7 {
        score -= 8.0 * (progress - 0.7) / 0.3;
    }

    // MUTATION (gen 45): cross-bin pair-closure lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count >= 2 {
        let need = next_item_size as f64 - dead;
        let pool = mean_residual.max(1.0);
        if pool >= need * 0.9 && need > 0.0 {
            let coop = (1.0 - (pool - need).abs() / need.max(1.0)).clamp(0.0, 1.0);
            score -= 5.0 * coop * coop * (0.4 + 0.6 * progress)
                * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
        }
    }

    // MUTATION (gen 45): residual-harmonic depth-2 tiling.
    if next_item_size >= 2 && post_residual >= 2 * next_item_size {
        let rem2 = post_residual % next_item_size;
        let tiles = post_residual / next_item_size;
        if tiles >= 2 && tiles <= 5 {
            let depth_pull = (tiles as f64 - 1.0) / 4.0;
            score -= 3.5 * depth_pull * (1.0 - rem2 as f64 / next_item_size as f64) * (0.5 + 0.5 * progress);
        }
        if rem2 == 0 && tiles >= 2 {
            score -= 4.0 * (1.0 - 1.0 / tiles as f64) * (0.3 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
