        if gap <= 3 {
            score -= 2.0 + 0.5 * (3 - gap) as f64;
        }
        // MUTATION (gen 45): prefer the largest residual in the miss band.
        if gap <= 5 {
            score -= 2.0 * (5.0 - gap as f64) / 5.0 * (1.0 - progress);
        }
