    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pool = mean_residual.max(1.0);
        if dead <= pool {
            let absorb = 1.0 - (dead / pool);
            score -= 3.0 * absorb * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // MUTATION (gen 45): dead-space saturation ramp — escalate stranded
    // space beyond half the next item's size with a cubic ramp so wide
