    if post_residual > 0 && next_item_size > 0 {
        let horizon = (next_item_size as f64 * 0.5).max(1.0);
        if dead > horizon {
            let excess = ((dead - horizon) / (cap - horizon)).clamp(0.0, 1.0);
            score += 9.0 * excess * excess * excess * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - dead / horizon) * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
